<template>
  <CollapseSection
    :title="title"
    :icon="resolveIcon(icon)"
    :color="color"
    :level="level"
    :depth="depth"
    :expanded="defaultExpanded ?? true"
  >
    <!-- position -->
    <FieldRow label="position" hint="position" :required="required">
      <Vec3Input
        :values="position"
        :step="step"
        labels="X,Y,Z"
        @update:values="(v: number[]) => emit('update:position', v)"
      />
    </FieldRow>

    <!-- rotation -->
    <FieldRow label="rotation" hint="rotation" :required="required">
      <Vec3Input
        :values="rotation"
        :step="1"
        labels="X,Y,Z"
        @update:values="(v: number[]) => emit('update:rotation', v)"
      />
    </FieldRow>

    <!-- scale -->
    <FieldRow label="scale" hint="scale" :required="required">
      <Vec3Input
        :values="scale"
        :step="step"
        labels="X,Y,Z"
        @update:values="(v: number[]) => emit('update:scale', v)"
      />
    </FieldRow>

    <!-- Gizmo 切换 + 模式选择 + 飞到此处 -->
    <div class="gizmo-toggle-row">
      <button
        class="gizmo-toggle"
        :class="{ active: gizmoActive }"
        @click="emit('toggle-gizmo', !gizmoActive)"
      >
        <Move3d :size="14" />
        <span>{{ gizmoActive ? '关闭 Gizmo' : 'Gizmo 拖动编辑' }}</span>
      </button>

      <!-- 模式切换按钮（仅在 gizmo 激活时显示） -->
      <div v-if="gizmoActive" class="gizmo-mode-group">
        <button
          v-for="m in modes"
          :key="m.value"
          class="gizmo-mode-btn"
          :class="{ active: gizmoMode === m.value }"
          :title="m.label"
          @click="emit('update:gizmoMode', m.value)"
        >
          <component :is="m.icon" :size="13" />
        </button>
      </div>

      <!-- 飞到此处：摄像机 tween 到 transform 位置 -->
      <button
        class="fly-to-btn"
        title="摄像机飞到此处"
        @click="emit('fly-to', position)"
      >
        <Navigation :size="14" />
        <span>飞到此处</span>
      </button>
    </div>
  </CollapseSection>
</template>

<script setup lang="ts">
import { Move3d, Move, RotateCw, Maximize2, Scaling, Navigation } from 'lucide-vue-next';
import CollapseSection from './CollapseSection.vue';
import FieldRow from './FieldRow.vue';
import Vec3Input from './Vec3Input.vue';
import { resolveIcon } from '../schema/icon-registry';
import type { GizmoMode } from '../composables/useGizmoBridge';

defineProps<{
  title: string;
  icon?: string;
  color?: string;
  level?: 1 | 2;
  depth?: number;
  defaultExpanded?: boolean;
  required?: boolean;
  position: number[];
  rotation: number[];
  scale: number[];
  step?: number;
  gizmoActive?: boolean;
  gizmoMode?: GizmoMode;
}>();

const emit = defineEmits<{
  (e: 'update:position', v: number[]): void;
  (e: 'update:rotation', v: number[]): void;
  (e: 'update:scale', v: number[]): void;
  (e: 'toggle-gizmo', active: boolean): void;
  (e: 'update:gizmoMode', mode: GizmoMode): void;
  (e: 'fly-to', position: number[]): void;
}>();

const modes: { value: GizmoMode; label: string; icon: typeof Move }[] = [
  { value: 'translate', label: '移动 (T)', icon: Move },
  { value: 'rotate', label: '旋转 (R)', icon: RotateCw },
  { value: 'scale', label: '缩放 (S)', icon: Maximize2 },
  { value: 'resize', label: '尺寸 (Z)', icon: Scaling },
];
</script>

