<template>
  <div class="add-key-row">
    <!-- 左列：键名输入 -->
    <div class="add-key-label-col">
      <input
        class="me-input"
        type="text"
        placeholder="键名"
        :value="modelValue"
        @input="emit('update:modelValue', ($event.target as HTMLInputElement).value)"
        @keyup.enter="emit('add')"
      />
    </div>
    <!-- 右列：类型选择 + 添加按钮 -->
    <div class="add-key-control-col">
      <select
        v-if="showType"
        class="me-select"
        :value="keyType"
        @change="emit('update:keyType', ($event.target as HTMLSelectElement).value)"
      >
        <option value="string">字符串</option>
        <option value="number">数字</option>
        <option value="boolean">布尔</option>
      </select>
      <button
        class="add-key-btn"
        :disabled="!modelValue.trim()"
        @click="emit('add')"
      >
        <Plus :size="12" :stroke-width="2.5" />
        <span>添加</span>
      </button>
    </div>
  </div>
</template>

<script setup lang="ts">
import { Plus } from 'lucide-vue-next';

defineProps<{
  modelValue: string;
  keyType?: string;
  showType?: boolean;
}>();

const emit = defineEmits<{
  (e: 'update:modelValue', value: string): void;
  (e: 'update:keyType', value: string): void;
  (e: 'add'): void;
}>();
</script>

