import {
  Sun,
  Cloud,
  Lightbulb,
  SunMedium,
  Lamp,
  Image,
  Camera,
  Smartphone,
  Box,
  MapPin,
  User,
  Sparkles,
  Settings,
  Palette,
} from 'lucide-vue-next';

export const iconRegistry: Record<string, any> = {
  Sun,
  Cloud,
  Lightbulb,
  SunMedium,
  Lamp,
  Image,
  Camera,
  Smartphone,
  Box,
  MapPin,
  User,
  Sparkles,
  Settings,
  Palette,
};

/** 通过字符串名取图标组件，未注册时返回 undefined */
export const resolveIcon = (name?: string): any | undefined => {
  if (!name) return undefined;
  return iconRegistry[name];
};
