/**
 * 返回字段标识符本身作为 label。
 * 中文翻译统一由 widget-schemas.ts 和 TOP_LEVEL_WIDGET_META_OVERRIDES 提供；
 * 这里不再做 camelCase→英文拆词（如 "Spherical Harmonics Degree"），
 * 因为这些英文 label 和原始字段名没有信息增量，
 * 且 hint 已经用等宽字体展示了字段路径。
 */
function humanizeLabel(value: string): string {
  return value;
}

function unwrapSchema(schema: z.ZodTypeAny): NormalizedSchemaNode {
  let current: any = schema;
  let required = true;

  while (true) {
    if (current instanceof z.ZodOptional || current instanceof z.ZodDefault || current instanceof z.ZodNullable) {
      if (current instanceof z.ZodOptional || current instanceof z.ZodDefault) {
        required = false;
      }
      current = typeof (current as any).unwrap === 'function' ? (current as any).unwrap() : current;
      continue;
    }

    if (current instanceof z.ZodLazy) {
      current = current._def.getter();
      continue;
    }

    // z.preprocess 解包：兼容 zod v3 兼容层 (ZodEffects + _def.effect.type==='preprocess', 内层在 _def.schema)
    // 与 zod v4 (ZodPreprocess, _def.type==='pipe', 内层在 _def.out)；v4 中 z.ZodEffects 为 undefined，需先守卫
    const ZodEffectsClass = (z as any).ZodEffects;
    if (ZodEffectsClass && current instanceof ZodEffectsClass && current._def?.effect?.type === 'preprocess') {
      current = current._def.schema;
      continue;
    }
    const ZodPreprocessClass = (z as any).ZodPreprocess;
    if (ZodPreprocessClass && current instanceof ZodPreprocessClass && current._def?.out) {
      current = current._def.out;
      continue;
    }

    break;
  }

  return { schema: current, required };
}


function getObjectShape(schema: z.ZodObject<any>): Record<string, z.ZodTypeAny> {
  return typeof schema.shape === 'function' ? schema.shape() : schema.shape;
}

function isTupleOfNumbers(schema: any, size?: number): boolean {
  if (!(schema instanceof z.ZodTuple)) return false;
  const tupleDef = schema as any;
  const items = Array.isArray(tupleDef?._def?.items) ? tupleDef._def.items : [];
  return (size === undefined || items.length === size) && items.every((item: any) => unwrapSchema(item).schema instanceof z.ZodNumber);
}


function isVector3ObjectSchema(schema: any): boolean {
  if (!(schema instanceof z.ZodObject)) return false;
  const shape = getObjectShape(schema);
  const keys = Object.keys(shape);
  return keys.length === 3 && ['x', 'y', 'z'].every((key) => unwrapSchema(shape[key]).schema instanceof z.ZodNumber);
}

function getNumberChecks(schema: any): { min?: number; max?: number } {
  const checks = Array.isArray(schema?._def?.checks) ? schema._def.checks : [];
  return checks.reduce((acc: { min?: number; max?: number }, check: any) => {
    if (check?.kind === 'min' && typeof check.value === 'number') acc.min = check.value;
    if (check?.kind === 'max' && typeof check.value === 'number') acc.max = check.value;
    return acc;
  }, {});
}

function applyFieldMetaOverride<T extends FieldDef>(field: T, override?: FieldMetaOverride): T {
  if (!override) {
    return field;
  }

  return {
    ...field,
    ...(override.label ? { label: override.label } : {}),
    ...(override.defaultValue !== undefined ? { defaultValue: override.defaultValue } : {}),
    ...(field.type === 'text' && override.placeholder ? { placeholder: override.placeholder } : {}),
  };
}

function createTextLikeField(path: string, label: string, required: boolean, fieldType: 'text' | 'textarea' | 'color' | 'url'): FieldText | FieldTextarea | FieldColor | FieldUrl {
  if (fieldType === 'url') {
    return {
      type: 'url',
      path,
      label,
      hint: path,
      required,
      defaultValue: '',
      urlMode: 'dual',
    };
  }

  if (fieldType === 'color') {
    return {
      type: 'color',
      path,
      label,
      hint: path,
      required,
      defaultValue: '#ffffff',
    };
  }

  if (fieldType === 'textarea') {
    return {
      type: 'textarea',
      path,
      label,
      hint: path,
      required,
      defaultValue: '',
      rows: 4,
    };
  }

  return {
    type: 'text',
    path,
    label,
    hint: path,
    required,
    defaultValue: '',
  };
}


function buildScalarField(path: string, label: string, normalized: NormalizedSchemaNode): FieldDef | null {
  const { schema, required } = normalized;
  const normalizedPath = path.toLowerCase();

  if (schema instanceof z.ZodEnum) {
    const field: FieldSelect = {
      type: 'select',
      path,
      label,
      hint: path,
      required,
      options: schema.options.map((option: any) => ({ value: String(option), label: String(option) })),
    };
    if (schema.options[0] !== undefined) {
      field.defaultValue = schema.options[0];
    }
    return field;
  }

  if (schema instanceof z.ZodBoolean) {
    return {
      type: 'switch',
      path,
      label,
      hint: path,
      inline: true,
      required,
      defaultValue: false,
    };
  }

  if (schema instanceof z.ZodNumber) {
    const checks = getNumberChecks(schema);
    const hasRange = typeof checks.min === 'number' || typeof checks.max === 'number';
    if (hasRange) {
      const field: FieldSlider = {
        type: 'slider',
        path,
        label,
        hint: path,
        required,
        min: checks.min ?? 0,
        max: checks.max ?? 100,
        step: 0.1,
        defaultValue: checks.min ?? 0,
      };
      return field;
    }

    const field: FieldNumber = {
      type: 'number',
      path,
      label,
      hint: path,
      required,
      step: 0.1,
      defaultValue: 0,
    };
    if (typeof checks.min === 'number') field.min = checks.min;
    if (typeof checks.max === 'number') field.max = checks.max;
    return field;
  }

  if (schema instanceof z.ZodString) {
    if (URL_FIELD_PATTERN.test(normalizedPath)) {
      // special: singleSceneConfigPath 支持本地导入（bundleDir: 'single-scene'）
      if (normalizedPath === 'singlesceneconfigpath') {
        return {
          type: 'url',
          path,
          label,
          hint: path,
          required,
          defaultValue: '',
          urlMode: 'dual',
          bundleDir: 'single-scene',
          accept: '.splat,.ksplat,.ply,.json',
        };
      }
      // special: regionReplaceConfigPath 仅支持远程 URL
      if (normalizedPath === 'regionreplaceconfigpath') {
        return {
          type: 'url',
          path,
          label,
          hint: path,
          required,
          defaultValue: '',
          urlMode: 'remote-only',
        };
      }
      return createTextLikeField(path, label, required, 'url');
    }
    if (COLOR_FIELD_PATTERN.test(normalizedPath)) {
      return createTextLikeField(path, label, required, 'color');
    }
    if (TEXTAREA_FIELD_PATTERN.test(normalizedPath)) {
      return createTextLikeField(path, label, required, 'textarea');
    }
    return createTextLikeField(path, label, required, 'text');
  }

  return null;
}

function buildVec3Field(path: string, label: string, normalized: NormalizedSchemaNode): FieldVec3 | null {
  const schema = normalized.schema;
  if (isTupleOfNumbers(schema, 3) || isVector3ObjectSchema(schema)) {
    return {
      type: 'vec3',
      path,
      label,
      hint: path,
      required: normalized.required,
      step: 0.01,
      defaultValue: isVector3ObjectSchema(schema) ? { x: 0, y: 0, z: 0 } : [0, 0, 0],
    };
  }

  if (schema instanceof z.ZodArray && VEC3_FIELD_PATTERN.test(path)) {
    const itemSchema = unwrapSchema((schema as any).element).schema;

    if (itemSchema instanceof z.ZodNumber) {
      return {
        type: 'vec3',
        path,
        label,
        hint: path,
        required: normalized.required,
        step: 0.01,
        defaultValue: [0, 0, 0],
      };
    }
  }

  return null;
}

function buildFieldsFromObjectSchema(schema: z.ZodObject<any>): FieldDef[] {
  return Object.entries(getObjectShape(schema))
    .map(([key, childSchema]) => buildFieldFromSchema(key, childSchema as z.ZodTypeAny))
    .filter((field): field is FieldDef => Boolean(field));
}

function buildArrayField(path: string, label: string, normalized: NormalizedSchemaNode): FieldArray | null {
  const arraySchema = normalized.schema;
  const itemSchema = arraySchema instanceof z.ZodArray ? arraySchema.element : typeof arraySchema.unwrap === 'function' ? arraySchema.unwrap() : null;
  if (!itemSchema) {
    return null;
  }

  const itemNormalized = unwrapSchema(itemSchema);
  const itemLabel = label.endsWith('列表') ? label.slice(0, -2) : label;

  if (itemNormalized.schema instanceof z.ZodObject) {
    const itemFields = buildFieldsFromObjectSchema(itemNormalized.schema);
    const shape = getObjectShape(itemNormalized.schema);
    const titleKey = ['name', 'id', 'label', 'title'].find((key) => key in shape);
    // 统一使用 buildObjectSkeleton 生成默认项骨架，与 Record variant 的 recordValueSkeleton 保持一致
    const defaultItem = buildObjectSkeleton(itemNormalized.schema);

    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index, item) => {
        if (titleKey && item && typeof item === 'object') {
          const title = (item as Record<string, unknown>)[titleKey];
          if (typeof title === 'string' && title) return title;
        }
        return `${path || 'item'}[${index}]`;
      },
      itemColor: () => ARRAY_COLOR,
      itemSchema: itemFields,
      defaultItem: () => JSON.parse(JSON.stringify(defaultItem)),
      defaultValue: [],
    };
  }

  if (itemNormalized.schema instanceof z.ZodString) {
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index, item) => (typeof item === 'string' && item ? item : `[${index}]`),
      itemColor: () => ARRAY_COLOR,
      itemSchema: [
        {
          type: 'text',
          path: '',
          label: itemLabel,
          hint: `${path}[]`,
        },
      ],
      defaultItem: () => '' as unknown as Record<string, unknown>,
      defaultValue: [],
    };
  }

  if (itemNormalized.schema instanceof z.ZodNumber && VEC3_FIELD_PATTERN.test(path)) {
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index) => `[${index}]`,
      itemColor: () => ARRAY_COLOR,
      itemSchema: [
        {
          type: 'number',
          path: '',
          label: itemLabel,
          hint: `${path}[]`,
          step: 0.1,
        },
      ],
      defaultItem: () => 0 as unknown as Record<string, unknown>,
      defaultValue: [],
    };
  }

  // 通用数字数组（如 geometry: z.array(z.number())）
  if (itemNormalized.schema instanceof z.ZodNumber) {
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index) => `[${index}]`,
      itemColor: () => ARRAY_COLOR,
      itemSchema: [
        {
          type: 'number',
          path: '',
          label: itemLabel,
          hint: `${path}[]`,
          step: 0.1,
        },
      ],
      defaultItem: () => 0 as unknown as Record<string, unknown>,
      defaultValue: [],
    };
  }

  return null;
}

function buildGroupField(path: string, label: string, normalized: NormalizedSchemaNode): FieldGroup | FieldTransform | null {
  if (!(normalized.schema instanceof z.ZodObject)) {
    return null;
  }

  const shape = getObjectShape(normalized.schema);

  // 识别 transformSchema：ZodObject 含 position / rotation / scale 三个 vec3 tuple → type:'transform'（Gizmo 可用）
  if (isTransformShape(shape)) {
    return {
      type: 'transform',
      path,
      label,
      hint: path,
      required: normalized.required,
      color: GROUP_COLOR,
      step: 0.01,
      defaultValue: { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
    };
  }

  return {
    type: 'group',
    path,
    label,
    hint: path,
    required: normalized.required,
    color: GROUP_COLOR,
    children: buildFieldsFromObjectSchema(normalized.schema),
    defaultValue: {},
  };
}

/** zod transformSchema 判定：ZodObject 含 position / rotation / scale 三个 vec3 tuple */
function isTransformShape(shape: Record<string, any>): boolean {
  const keys = Object.keys(shape);
  if (keys.length < 2 || keys.length > 3) return false;
  const hasPos = ['position', 'rotation', 'scale'].some((k) => keys.includes(k));
  if (!hasPos) return false;
  return ['position', 'rotation', 'scale'].every((k) => {
    if (!(k in shape)) return true;
    const child = (shape[k] as any)?._def?.innerType ?? shape[k];
    return isTupleOfNumbers(child, 3);
  });
}

function buildFieldFromSchema(path: string, schema: z.ZodTypeAny, override?: FieldMetaOverride): FieldDef | null {
  const label = override?.label ?? humanizeLabel(path);
  const normalized = unwrapSchema(schema);

  const vec3Field = buildVec3Field(path, label, normalized);
  if (vec3Field) return applyFieldMetaOverride(vec3Field, override);

  const scalarField = buildScalarField(path, label, normalized);
  if (scalarField) return applyFieldMetaOverride(scalarField, override);

  if (normalized.schema instanceof z.ZodArray) {
    const arrayField = buildArrayField(path, label, normalized);
    return arrayField ? applyFieldMetaOverride(arrayField, override) : null;
  }

  if (normalized.schema instanceof z.ZodObject) {
    const groupField = buildGroupField(path, label, normalized);
    return groupField ? applyFieldMetaOverride(groupField, override) : null;
  }

  if (normalized.schema instanceof z.ZodUnion) {
    const options = (normalized.schema as any)._def?.options ?? [];
    for (const option of options) {
      const field = buildFieldFromSchema(path, option);
      if (field) return applyFieldMetaOverride(field, override);
    }
    return null;
  }

  return null;
}


function mergeWidgetFields(baseFields: FieldDef[] | undefined, generatedFields: FieldDef[]): FieldDef[] {
  const existingPaths = new Set((baseFields ?? []).map((field) => field.path));
  return [...(baseFields ?? []), ...generatedFields.filter((field) => !existingPaths.has(field.path))];
}



function resolveSchemaAtPath(schema: z.ZodTypeAny, path: string): z.ZodTypeAny | null {
  const segments = path.split('.').filter(Boolean);
  let current: z.ZodTypeAny = schema;

  for (const segment of segments) {
    const normalized = unwrapSchema(current);
    if (!(normalized.schema instanceof z.ZodObject)) {
      return null;
    }
    const shape = getObjectShape(normalized.schema);
    const next = shape[segment] as z.ZodTypeAny | undefined;
    if (!next) {
      return null;
    }
    current = next;
  }

  return current;
}

function getTopLevelShape(schema: z.ZodTypeAny): Record<string, z.ZodTypeAny> {
  const normalized = unwrapSchema(schema);
  if (!(normalized.schema instanceof z.ZodObject)) {
    return {};
  }
  return getObjectShape(normalized.schema);
}

/**
 * 从 ZodObject 递归提取默认值骨架。
 * 每个字段取 Zod schema 的 defaultValue 或按类型推断（string→'', number→0, boolean→false）。
 */
function buildObjectSkeleton(schema: z.ZodObject<any>): Record<string, unknown> {
  const shape = getObjectShape(schema);

  // transform schema（position/rotation/scale 三元组）→ 返回标准 transform 骨架
  // 必须在逐字段遍历前短路，否则 ZodTuple 子段不会被处理，得到空 {}
  if (isTransformShape(shape)) {
    return { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] };
  }

  const skeleton: Record<string, unknown> = {};
  for (const [key, childSchema] of Object.entries(shape)) {
    const normalized = unwrapSchema(childSchema as z.ZodTypeAny);
    const def = (childSchema as any)?._def;
    // 有显式 .default() 的字段 → 始终包含（schema 作者明确指定了默认值）
    if (def?.defaultValue !== undefined && typeof def.defaultValue !== 'function') {
      skeleton[key] = def.defaultValue;
      continue;
    }
    // 可选字段（无显式 .default()）→ 不写入骨架
    // 编辑器以占位行 + "+ 添加"按钮呈现，用户主动添加后才写入
    if (!normalized.required) {
      continue;
    }
    if (normalized.schema instanceof z.ZodString) skeleton[key] = '';
    else if (normalized.schema instanceof z.ZodNumber) skeleton[key] = 0;
    else if (normalized.schema instanceof z.ZodBoolean) skeleton[key] = false;
    else if (normalized.schema instanceof z.ZodObject) skeleton[key] = buildObjectSkeleton(normalized.schema);
    else if (normalized.schema instanceof z.ZodArray) skeleton[key] = [];
    else if (normalized.schema instanceof z.ZodTuple) {
      // vec3 tuple（如 position: [number, number, number]）→ 生成对应长度的零数组
      const items = (normalized.schema as any)._def?.items ?? [];
      skeleton[key] = items.map(() => 0);
    }
  }
  return skeleton;
}

/**
 * 从 ZodUnion 生成 WidgetVariant 列表。
 *
 * 支持 ZodObject / ZodArray / ZodRecord 三种 union 分支：
 * - ZodObject → variant rootPath = id，fields 从对象 schema 生成
 * - ZodArray → variant rootPath = ''，field path = id（数组控件）
 * - ZodRecord → variant rootPath = ''，field path = id（auto-object 控件）
 */
function buildUnionVariants(id: string, unionSchema: z.ZodUnion<any>): WidgetVariant[] {
  const options = (unionSchema as any)._def?.options ?? [];
  const variants: WidgetVariant[] = [];

  for (const [index, option] of options.entries()) {
    const normalized = unwrapSchema(option);
    const schema = normalized.schema;

    if (schema instanceof z.ZodArray) {
      const arrayField = buildArrayField(id, humanizeLabel(id), normalized);
      if (arrayField) {
        variants.push({
          id: 'array',
          label: 'Array',
          rootPath: '',
          fields: [arrayField],
          defaultSkeleton: { [id]: [] },
          match: (data: unknown) => Array.isArray(data),
        });
      }
    } else if (schema instanceof z.ZodRecord) {
      const recordDef = (schema as any)._def;
      const valueSchema = recordDef.valueType;
      const valueNormalized = unwrapSchema(valueSchema);

      const autoObjectField: any = {
        type: 'auto-object',
        path: id,
        label: humanizeLabel(id),
        hint: id,
        required: normalized.required,
        color: ARRAY_COLOR,
        defaultExpanded: true,
      };

      // Record 值为结构化对象（如 interactionZoneSchema）→ 携带字段定义和骨架
      if (valueNormalized.schema instanceof z.ZodObject) {
        autoObjectField.recordValueSchema = buildFieldsFromObjectSchema(valueNormalized.schema);
        autoObjectField.recordValueSkeleton = buildObjectSkeleton(valueNormalized.schema);
      }

      variants.push({
        id: 'record',
        label: 'Record',
        rootPath: '',
        fields: [autoObjectField],
        defaultSkeleton: { [id]: {} },
        match: (data: unknown) => data != null && typeof data === 'object' && !Array.isArray(data),
      });
    } else if (schema instanceof z.ZodObject) {
      const shape = getObjectShape(schema);
      const keys = Object.keys(shape);
      const hasUrl = 'url' in shape;
      const hasTransform = 'transform' in shape;
      const hasModules = 'modules' in shape;
      const hasLoadConfig = 'loadConfig' in shape;

      let variantId = `${id}-${index}`;
      let variantLabel = `${humanizeLabel(id)} ${index + 1}`;
      let matcher = (data: unknown) => data != null && typeof data === 'object' && !Array.isArray(data);

      if (id === 'collision') {
        if (hasUrl && hasTransform) {
          variantId = 'legacy';
          variantLabel = 'Legacy';
          matcher = (data: unknown) => {
            if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
            return 'url' in (data as Record<string, unknown>) || 'transform' in (data as Record<string, unknown>);
          };
        } else if (hasModules && hasLoadConfig) {
          variantId = 'chunked';
          variantLabel = 'Chunked';
          matcher = (data: unknown) => {
            if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
            return 'modules' in (data as Record<string, unknown>) || 'loadConfig' in (data as Record<string, unknown>);
          };
        }
      } else if (keys.length > 0) {
        variantId = keys[0];
        variantLabel = humanizeLabel(keys[0]);
        matcher = (data: unknown) => {
          if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
          return keys.some((key) => key in (data as Record<string, unknown>));
        };
      }

      variants.push({
        id: variantId,
        label: variantLabel,
        rootPath: id,
        fields: buildFieldsFromObjectSchema(schema),
        defaultSkeleton: { [id]: buildObjectSkeleton(schema) },
        match: matcher,
      });
    }
  }

  return variants;
}

function buildAutoWidget(id: string, schema: z.ZodTypeAny): WidgetSchema {
  const normalized = unwrapSchema(schema);
  const isObjectWidget = normalized.schema instanceof z.ZodObject;
  const isUnionWidget = normalized.schema instanceof z.ZodUnion;
  const widgetMeta = TOP_LEVEL_WIDGET_META_OVERRIDES[id];
  const label = widgetMeta?.label ?? id;

  if (isUnionWidget) {
    const variants = buildUnionVariants(id, normalized.schema);
    const firstVariant = variants[0];
    return {
      id,
      label,
      rootPath: '',
      desc: widgetMeta?.desc ?? label,
      info: widgetMeta?.info,
      required: widgetMeta?.required ?? normalized.required,
      fields: firstVariant?.fields ?? [],
      variants,
    };
  }

  return {
    id,
    label,
    rootPath: isObjectWidget ? id : '',
    desc: widgetMeta?.desc ?? label,
    info: widgetMeta?.info,
    required: widgetMeta?.required ?? normalized.required,
    fields: isObjectWidget ? buildFieldsFromObjectSchema(normalized.schema) : [buildFieldFromSchema(id, schema, TOP_LEVEL_FIELD_META_OVERRIDES[id])].filter((field): field is FieldDef => Boolean(field)),
  };
}







function mergeWidget(baseWidget: WidgetSchema | undefined, generatedWidget: WidgetSchema): WidgetSchema {
  if (!baseWidget) {
    return generatedWidget;
  }

  return {
    ...generatedWidget,
    ...baseWidget,
    fields: mergeWidgetFields(baseWidget.fields, generatedWidget.fields ?? []),
    variants: generatedWidget.variants ?? baseWidget?.variants,
  };
}

function buildWidgetsFromSchema(rootSchema: z.ZodTypeAny, baseWidgets: WidgetSchema[] = []): WidgetSchema[] {
  const shape = getTopLevelShape(rootSchema);
  const baseWidgetMap = new Map(baseWidgets.map((widget) => [widget.id, widget]));
  const autoWidgetIds = Object.keys(shape).filter((id) => !CONSUMED_TOP_LEVEL_KEYS.has(id));
  const allWidgetIds = new Set<string>([
    ...autoWidgetIds,
    ...baseWidgets.map((widget) => widget.id),
  ]);

  const orderedIds = [
    ...DEFAULT_WIDGET_ORDER.filter((id) => allWidgetIds.has(id)),
    ...Array.from(allWidgetIds).filter((id) => !DEFAULT_WIDGET_ORDER.includes(id as typeof DEFAULT_WIDGET_ORDER[number])).sort(),
  ];

  return orderedIds.map((id) => {
    const baseWidget = baseWidgetMap.get(id);
    const schema = shape[id] ?? (baseWidget?.rootPath ? (resolveSchemaAtPath(rootSchema, baseWidget.rootPath) as any) : null);

    if (!schema) {
      return baseWidget!;
    }

    const generatedWidget = buildAutoWidget(id, schema);
    const generatedRootPath = Object.prototype.hasOwnProperty.call(shape, id)
      ? generatedWidget.rootPath
      : baseWidget?.rootPath ?? generatedWidget.rootPath;

    generatedWidget.rootPath = generatedRootPath;
    return mergeWidget(baseWidget, generatedWidget);
  }).filter((widget): widget is WidgetSchema => Boolean(widget));
}



/**
 * 通过共享 zod schema 生成 editor rules：
 * - 顶层 widgets 默认从 ProjectConfig schema 自动派生
 * - widget-schemas.ts 只保留复杂控件、树行为和文案的 override
 * - 未手写覆盖的字段按 schema 语义自动生成
 */
export function buildEditorRules(options: BuildEditorRulesOptions): EditorRules {
  const mode = options.mode ?? 'hybrid';
  const useBaseRules = mode === 'hybrid';
  const includeSpecialWidgets = options.includeSpecialWidgets ?? true;
  const baseRules = useBaseRules ? projectConfigEditorRules : {
    version: '1.0',
    autoInferUnknownTopKeys: false,
    treeTitle: '操作菜单',
    widgets: [],
  };
  const widgets = buildWidgetsFromSchema(options.schema, useBaseRules ? projectConfigEditorRules.widgets : []);

  return {
    ...baseRules,
    widgets: includeSpecialWidgets ? applySpecialWidgets(widgets, options.schema) : widgets,
  };
}

export const zodOnlyEditorRules: EditorRules = buildEditorRules({
  schema: projectConfigSchema as unknown as z.ZodTypeAny,
  mode: 'zod',
});



