<template>
  <div class="collapse-section" :class="[`level-${level}`, { expanded: isExpanded }]"
    :style="sectionStyle">
    <button class="collapse-header" @click="toggle">
      <div class="collapse-header-left">
        <ChevronRight :size="level === 1 ? 14 : 13" class="collapse-arrow" />
        <component
          v-if="icon && level === 1"
          :is="icon"
          :size="14"
          :stroke-width="2"
          class="section-icon"
        />
        <span class="section-title">
          {{ title }}
          <span v-if="required" class="required-mark" title="必填字段">*</span>
        </span>
        <span v-if="badge" class="section-badge">{{ badge }}</span>
        <span v-if="!hasContent && level === 1" class="empty-flag">未配置</span>
      </div>
      <div v-if="hasActions || removable" class="collapse-header-right">
        <span v-if="hasActions" class="header-actions" @click.stop>
          <slot name="actions" />
        </span>
        <button
          v-if="removable"
          class="header-remove-btn"
          title="移除该分组"
          @click.stop="emit('remove')"
        >
          <X :size="12" />
        </button>
      </div>
    </button>
    <Transition name="me-collapse">
      <div v-if="isExpanded && hasContent" class="collapse-body">
        <slot />
      </div>
    </Transition>
  </div>
</template>

<script setup lang="ts">
import { ref, useSlots, computed } from 'vue';
import { ChevronRight, X } from 'lucide-vue-next';

const props = withDefaults(
  defineProps<{
    title: string;
    icon?: any;
    color?: string;
    expanded?: boolean;
    /** 层级：1=强分组(卡片), 2=弱分组(列表项) */
    level?: 1 | 2;
    /** 标题右侧的徽章（如计数 "3 项"、状态等） */
    badge?: string;
    /** 是否为必填字段（标题加红 *） */
    required?: boolean;
    /** 是否显示标题右侧 − 移除按钮 */
    removable?: boolean;
    /** 嵌套深度：0=顶层，每深入一层 +1，用于自动计算背景色 */
    depth?: number;
  }>(),
  { color: '#a1a1aa', expanded: false, level: 1, required: false, removable: false, depth: 0 },
);

const emit = defineEmits<{
  (e: 'remove'): void;
}>();

const isExpanded = ref(props.expanded);
const slots = useSlots();
const hasContent = computed(() => !!slots.default && !!slots.default().length);
const hasActions = computed(() => !!slots.actions);

/**
 * 按嵌套深度自动计算背景色（UE 灰阶：越深越暗）
 *
 * 规则：
 * - section/header 不刷背景（透明），与同级 FieldRow 保持一致
 * - body（内容区）用 depthBg 体现父子层级：每深入一层 -3%
 * - depth=0 → 10%（#1a1a1a，比面板 #1f1f1f 暗一个台阶），最深 5%，避免纯黑
 * - hover 比当前深度亮 2%（交互反馈）
 */
const depthLightness = computed(() => Math.max(10 - props.depth * 3, 5));
const depthBg = computed(() => `hsl(0, 0%, ${depthLightness.value}%)`);
const depthBgDarker = computed(() => `hsl(0, 0%, ${Math.max(depthLightness.value - 2, 3)}%)`);
const depthBgHover = computed(() => `hsl(0, 0%, ${Math.min(depthLightness.value + 2, 28)}%)`);

/** 合并色系和深度背景到 :style 对象（避免 computed ref 在对象字面量中不解包的坑） */
const sectionStyle = computed(() => ({
  '--section-color': props.color,
  '--me-depth-bg': depthBg.value,
  '--me-depth-bg-darker': depthBgDarker.value,
  '--me-depth-bg-hover': depthBgHover.value,
}));

const toggle = () => {
  if (hasContent.value) isExpanded.value = !isExpanded.value;
};
</script>

<style scoped>
