<script setup lang="ts">
import { ref, computed, reactive, watch, onMounted, onBeforeUnmount, nextTick } from 'vue';
import TopBar from './components/TopBar.vue';
import LeftSidebar from './components/LeftSidebar.vue';
import SceneTreePanel from './components/SceneTreePanel.vue';
import PropertyPanel from './components/PropertyPanel.vue';
import RawModePanel from './components/RawModePanel.vue';
import PreviewPanel from './components/PreviewPanel.vue';
import Splitter from './components/Splitter.vue';
import Toast, { pushToast } from './components/Toast.vue';
import ConfirmDialog, { confirmDialog } from './components/ConfirmDialog.vue';
import BusyOverlay, { beginBusy } from './components/BusyOverlay.vue';
import ImportSourceDialog, { importSourceDialog } from './components/ImportSourceDialog.vue';
import { mockMetaJson } from './mockMeta';
import { buildProjectConfigSkeleton } from '@tencent/viewer-sdk';
import { buildEditorRules, zodOnlyEditorRules } from './schema/build-editor-rules';

import { projectConfigSchema } from '@tencent/viewer-sdk';

import { buildDefaultCamera } from './schema/special-widgets';

import { z } from 'zod';


import { setByPath, removeAtPath, getByPath } from './schema/path-utils';
import { validateRequiredFields } from './schema/validate';
import * as FileBundle from './schema/file-bundle';
import { useGizmoBridge, deactivateGizmo, syncGizmoTransform, activateGizmoMulti, notifyGeometryChange } from './composables/useGizmoBridge';
import type { GizmoEntry, GizmoTransform } from './composables/useGizmoBridge';
import {
  loadFromFiles,
  type LoadReport,
  isFileSystemAccessSupported,
  pickDirectoryHandle,
  loadFromDirectoryHandle,
  fetchByPath,
} from './schema/assets-loader';
import JSZip from 'jszip';
import type { EditorRules, WidgetSchema, WidgetVariant } from './schema/types';
import './theme.css';

/**
 * MetaEditor 是通用 JSON 表单编辑器壳子。
 *
 * 调用方传入：
 * - :value  待编辑的 JSON 数据（任意结构）
 * - :rules  字段→控件 映射规则（可外部注入；缺省走默认规则 + 自动推断）
 *
 * 不传时使用 mockMeta + defaultEditorRules 作为 demo 默认值。
 *
 * **响应式策略**：将 props.value 深拷贝到内部 reactive 副本（meta），
 * 所有添加/移除/编辑都在副本上 mutate，避免污染外部传入的 plain object，
 * 同时让 Vue 能追踪深层属性变化（外部 plain object 的 delete/set 不会触发更新）。
 */
const props = withDefaults(
  defineProps<{
    value?: any;
    rules?: EditorRules;
    useWidgetSchemas?: boolean;
    includeSpecialWidgets?: boolean;
  }>(),

  {
    // 默认进入空白引导态（不再塞 mockMetaJson 让用户误以为是自己的项目）。
    // 用户通过顶栏文件菜单或场景层级面板的引导按钮触发：新建 / 导入 / 加载示例
    value: () => ({}),
    rules: undefined,
    useWidgetSchemas: false,
    includeSpecialWidgets: true,

  },
);



/** 内部响应式数据副本；props.value 变化时同步重置 */
const meta = reactive<Record<string, any>>(deepClone(props.value));
normalizeMeta(meta);

watch(
  () => props.value,
  (newVal) => {
    // 清空旧 keys 再赋新值，保持 reactive 引用稳定
    for (const k of Object.keys(meta)) delete meta[k];
    Object.assign(meta, deepClone(newVal));
    normalizeMeta(meta);
  },
);

const value = computed(() => meta);
const internalRules = computed(() => {
  if (props.includeSpecialWidgets) return zodOnlyEditorRules;
  return buildEditorRules({
    schema: projectConfigSchema as unknown as z.ZodTypeAny,
    mode: 'zod',
    includeSpecialWidgets: props.includeSpecialWidgets,
  });
});
const rules = computed(() => props.rules ?? internalRules.value);






/** 简单深拷贝（mockMeta 是纯 JSON 形态，无 Date/Map/循环引用，足够用） */
function deepClone<T>(v: T): T {
  return v == null ? v : JSON.parse(JSON.stringify(v));
}

/**
 * 对导入 / raw 应用 / 示例数据做安全结构迁移。
 *
 * 已确定升级方向的字段：
 * 1. 旧版 `initial.player.position/rotation` → `initial.player.transform.{position,rotation,scale}`
 * 2. 旧版 InteractionZone 扁平字段 → v2 嵌套格式（geometry/model 分离 + transform 统一）
 *
 * `initial.camera` 等存在语义歧义的历史字段仍不做静默迁移。
 */
function normalizeMeta(m: Record<string, any>): void {
  migratePlayerTransform(m);
  migrateInteractionZones(m);
}

function migratePlayerTransform(m: Record<string, any>): void {
  const player = m.initial?.player;
  if (!player || typeof player !== 'object' || Array.isArray(player)) return;

  const transform = player.transform && typeof player.transform === 'object' && !Array.isArray(player.transform)
    ? player.transform
    : {};

  const oldPosition = vectorToTuple(player.position, [0, 0, 0]);
  const oldRotation = vectorToTuple(player.rotation, [0, 0, 0]);
  const nextPosition = vectorToTuple(transform.position, oldPosition);
  const nextRotation = vectorToTuple(transform.rotation, oldRotation);
  const nextScale = vectorToTuple(transform.scale, [1, 1, 1]);

  if (player.transform !== transform || player.position !== undefined || player.rotation !== undefined) {
    player.transform = {
      ...transform,
      position: nextPosition,
      rotation: nextRotation,
      scale: nextScale,
    };
    delete player.position;
    delete player.rotation;
  }
}

/**
 * 把旧版 InteractionZone 扁平结构迁移到 v2 嵌套格式。
 *
 * 旧字段 → 新字段映射：
 * - `geometry: [w,h,d]` → `geometry.size: [w,h,d]`
 * - `geometryPos` / `geometryRotation` / `geometryScale` / `geometryTransform` → `geometry.transform.{position,rotation,scale}`
 * - `model: "url"` → `model.url: "url"`
 * - `modelPos` / `rotation` / `scale` / `transform` / `modelTransform` → `model.transform.{position,rotation,scale}`
 *
 * 同时处理 `interaction`（单个 zone）和 `interactionZones`（数组/Record）两种顶层容器。
 * 已是新格式的 zone 原样跳过（geometry 是对象且含 type 字段时视为已迁移）。
 */
function migrateInteractionZones(m: Record<string, any>): void {
  // interaction（单个 zone）
  if (m.interaction) {
    migrateSingleZone(m, 'interaction');
  }
  // interactionZones（数组或 Record）
  if (m.interactionZones) {
    const zones = m.interactionZones;
    if (Array.isArray(zones)) {
      zones.forEach((zone) => migrateZoneObject(zone));
    } else if (typeof zones === 'object' && zones !== null) {
      Object.values(zones).forEach((zone: any) => migrateZoneObject(zone));
    }
  }
}

function migrateSingleZone(m: Record<string, any>, key: string): void {
  const zone = m[key];
  if (!zone || typeof zone !== 'object' || Array.isArray(zone)) return;
  migrateZoneObject(zone);
}

function migrateZoneObject(zone: Record<string, any>): void {
  if (!zone || typeof zone !== 'object' || Array.isArray(zone)) return;

  // ── geometry 迁移 ──
  // 已是新格式（geometry 是对象且含 type）→ 跳过
  const geo = zone.geometry;
  const isGeoNew = geo && typeof geo === 'object' && !Array.isArray(geo) && geo.type !== undefined;
  const hasLegacyGeo = !isGeoNew && (Array.isArray(geo) || zone.geometryPos !== undefined || zone.geometryTransform !== undefined);

  if (hasLegacyGeo) {
    const gt = zone.geometryTransform;
    const legacySize = Array.isArray(geo) ? geo : [1, 1, 1];
    zone.geometry = {
      type: 'box',
      size: vectorToTuple(legacySize, [1, 1, 1]),
      transform: {
        position: vectorToTuple(gt?.position ?? zone.geometryPos, [0, 0, 0]),
        rotation: vectorToTuple(gt?.rotation ?? zone.geometryRotation, [0, 0, 0]),
        scale: vectorToTuple(gt?.scale ?? zone.geometryScale, [1, 1, 1]),
      },
    };
    delete zone.geometryPos;
    delete zone.geometryRotation;
    delete zone.geometryScale;
    delete zone.geometryTransform;
  }

  // ── model 迁移 ──
  // 已是新格式（model 是对象且含 url）→ 跳过
  const mdl = zone.model;
  const isModelNew = mdl && typeof mdl === 'object' && !Array.isArray(mdl) && mdl.url !== undefined;
  const hasLegacyModel = !isModelNew && (typeof mdl === 'string' || zone.modelPos !== undefined || zone.modelTransform !== undefined);

  if (hasLegacyModel) {
    const mt = zone.modelTransform;
    const legacyTransform = zone.transform;
    zone.model = {
      url: typeof mdl === 'string' ? mdl : '',
      transform: {
        position: vectorToTuple(mt?.position ?? zone.modelPos, [0, 0, 0]),
        rotation: vectorToTuple(mt?.rotation ?? zone.rotation ?? legacyTransform?.rotation, [0, 0, 0]),
        scale: vectorToTuple(mt?.scale ?? zone.scale ?? legacyTransform?.scale, [1, 1, 1]),
      },
    };
    delete zone.modelPos;
    delete zone.modelTransform;
    delete zone.scale;
    delete zone.rotation;
    delete zone.transform;
  }
}

function vectorToTuple(value: unknown, fallback: [number, number, number]): [number, number, number] {
  if (Array.isArray(value)) {
    return [numberOrFallback(value[0], fallback[0]), numberOrFallback(value[1], fallback[1]), numberOrFallback(value[2], fallback[2])];
  }
  if (value && typeof value === 'object') {
    const v = value as Record<string, unknown>;
    return [numberOrFallback(v.x, fallback[0]), numberOrFallback(v.y, fallback[1]), numberOrFallback(v.z, fallback[2])];
  }
  return fallback;
}

function numberOrFallback(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

const projectName = computed(() => {
  if (Object.keys(meta).length === 0) return '尚未打开项目';
  return value.value?.name || '未命名项目';
});
const activeTab = ref<'scene' | 'raw'>('scene');
const selectedWidgetId = ref<string | null>(null);

/** 是否处于"空白引导态"：meta 无任何 key（用户尚未新建/导入/加载示例） */
const isEmptyMeta = computed(() => Object.keys(meta).length === 0);

/**
 * Pristine 快照：表示"上次重置数据时的初始状态"。
 *
 * 在每个会清空/重置 meta 的入口（setMeta）调用后，把当前 meta 序列化为 JSON 字符串保存。
 * 后续每次比较"当前 meta JSON 化后是否与快照一致"得到 isDirty。
 *
 * 用 JSON 字符串而不是对象引用，是为了规避 reactive proxy 的引用稳定性问题，
 * 也避免深比较的性能消耗（JSON 序列化对纯数据足够快）。
 */
const pristineSnapshot = ref<string>(JSON.stringify(meta));

/** 当前 meta 是否相对 pristine 快照有变更 */
const isDirty = computed(() => {
  if (isEmptyMeta.value) return false;
  // 空字符串 vs '{}' 等价处理
  try {
    return JSON.stringify(meta) !== pristineSnapshot.value;
  } catch {
    return true;
  }
});

/** 当前选中 widget 的规则；找不到时返回 null（PropertyPanel 走 infer 兜底） */
const currentSchema = computed<WidgetSchema | null>(() => {
  if (!selectedWidgetId.value) return null;
  return rules.value.widgets.find((w) => w.id === selectedWidgetId.value) ?? null;
});

// ==================== 布局尺寸（可拖拽 + 持久化） ====================
const LS_KEYS = {
  leftWidth: 'meta-editor.leftWidth',
  treeHeight: 'meta-editor.treeHeight',
};
const LEFT_WIDTH_DEFAULT = 360;
const TREE_HEIGHT_DEFAULT = 320;

const winSize = ref({ w: window.innerWidth, h: window.innerHeight });

const readLS = (k: string, fallback: number): number => {
  try {
    const v = Number(localStorage.getItem(k));
    return Number.isFinite(v) && v > 0 ? v : fallback;
  } catch {
    return fallback;
  }
};
const writeLS = (k: string, v: number) => {
  try {
    localStorage.setItem(k, String(v));
  } catch {
    // ignore
  }
};

const leftWidth = ref(readLS(LS_KEYS.leftWidth, LEFT_WIDTH_DEFAULT));
const treeHeight = ref(readLS(LS_KEYS.treeHeight, TREE_HEIGHT_DEFAULT));

/** 左侧面板最大宽度：窗口宽度的 70%（保留 30% 给预览） */
const leftWidthMax = computed(() => Math.max(400, Math.floor(winSize.value.w * 0.7)));
/** 树面板最大高度：左侧内容区高度 - 120（保证属性面板至少有 120px） */
const treeHeightMax = computed(() => Math.max(200, Math.floor(winSize.value.h * 0.7)));
const treeHeightDefault = TREE_HEIGHT_DEFAULT;

const setLeftWidth = (v: number) => {
  leftWidth.value = v;
  writeLS(LS_KEYS.leftWidth, v);
};
const setTreeHeight = (v: number) => {
  treeHeight.value = v;
  writeLS(LS_KEYS.treeHeight, v);
};

// 监听窗口 resize，避免 leftWidth/treeHeight 超过新的可视范围
const onWinResize = () => {
  winSize.value = { w: window.innerWidth, h: window.innerHeight };
  if (leftWidth.value > leftWidthMax.value) leftWidth.value = leftWidthMax.value;
  if (treeHeight.value > treeHeightMax.value) treeHeight.value = treeHeightMax.value;
};
onMounted(() => {
  window.addEventListener('resize', onWinResize);
  window.addEventListener('beforeunload', onBeforeUnload);
});
onBeforeUnmount(() => {
  window.removeEventListener('resize', onWinResize);
  window.removeEventListener('beforeunload', onBeforeUnload);
});

// ==================== 事件 ====================

const onSwitchTab = (tab: 'scene' | 'raw') => {
  activeTab.value = tab;
};

const onSelectWidget = (id: string) => {
  selectedWidgetId.value = id;
};

/**
 * 选中 widget 时的 gizmo 策略：
 * - 有 transform 字段的 widget → 自动激活所有 transform 的 gizmo（批量操作）
 * - 无 transform 字段 / 未选中 → 关闭所有 gizmo
 */
watch(selectedWidgetId, (id) => {
  if (!id) {
    deactivateGizmo();
    return;
  }
  const entries = collectWidgetGizmoEntries(id);
  if (entries.length > 0) {
    activateGizmoMulti(entries);
  } else {
    deactivateGizmo();
  }
});

/**
 * 从 meta 中读取 transform 对象，构建 GizmoEntry。
 */
function makeGizmoEntry(path: string, transform: any): GizmoEntry {
  return {
    path,
    transform: {
      position: [transform.position?.[0] ?? 0, transform.position?.[1] ?? 0, transform.position?.[2] ?? 0],
      rotation: [transform.rotation?.[0] ?? 0, transform.rotation?.[1] ?? 0, transform.rotation?.[2] ?? 0],
      scale: [transform.scale?.[0] ?? 1, transform.scale?.[1] ?? 1, transform.scale?.[2] ?? 1],
    },
  };
}

/**
 * 判断对象是否是 transform 结构（含 position/rotation/scale 数组字段）。
 */
function isTransformLike(obj: any): boolean {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  const transformKeys = ['position', 'rotation', 'scale'];
  const hasAny = transformKeys.some((k) => k in obj);
  if (!hasAny) return false;
  return transformKeys.every((k) => !(k in obj) || Array.isArray(obj[k]));
}

/**
 * 递归扫描数据对象，找出所有 transform 结构及其路径。
 * 路径格式与 meta 路径一致：`[i]` 表示数组索引，`.` 表示对象属性。
 */
function findTransformsInData(obj: any, basePath: string, out: { path: string; transform: any }[]): void {
  if (!obj || typeof obj !== 'object') return;

  if (isTransformLike(obj)) {
    out.push({ path: basePath, transform: obj });
    return;
  }

  if (Array.isArray(obj)) {
    for (let i = 0; i < obj.length; i++) {
      findTransformsInData(obj[i], `${basePath}[${i}]`, out);
    }
  } else {
    for (const [key, val] of Object.entries(obj)) {
      findTransformsInData(val, basePath ? `${basePath}.${key}` : key, out);
    }
  }
}

/**
 * 选中 widget 时收集所有 transform 的 GizmoEntry。
 *
 * 纯数据驱动：扫描 widget rootPath 下的实际 meta 数据，
 * 找出所有含 position/rotation/scale 的 transform 对象，每个生成独立 gizmo。
 * 不依赖 schema 声明，因此对 infer 兜底字段（npcs.list、models 等）同样有效。
 *
 * Union widget（如 collision 有 legacy/chunked 变体）的 rootPath 为 ''，
 * 需从匹配的 variant 解析有效 rootPath。
 */
function collectWidgetGizmoEntries(widgetId: string): GizmoEntry[] {
  if (widgetId === 'interactionZones') {
    return collectInteractionZoneGizmoEntries();
  }

  const widget = rules.value.widgets.find((w) => w.id === widgetId);
  if (!widget) return [];

  // 解析有效 rootPath
  let rootPath = widget.rootPath || '';
  if (!rootPath && widget.variants?.length) {
    const widgetData = (meta as any)[widgetId];
    const matched = widget.variants.find((v) => v.match?.(widgetData));
    rootPath = matched?.rootPath || widgetId;
  }
  if (!rootPath) return [];

  // 纯数据驱动：扫描 rootPath 下所有 transform
  const rootData = getByPath(meta, rootPath);
  if (!rootData || typeof rootData !== 'object') return [];

  const found: { path: string; transform: any }[] = [];
  findTransformsInData(rootData, rootPath, found);

  return found.map((f) => makeGizmoEntry(f.path, f.transform));
}

/**
 * 遍历 meta.interactionZones，为每个 zone 收集 geometry.transform 和 model.transform 的 GizmoEntry。
 * 路径格式与 SchemaRenderer 中 joinPath(basePath, `${field.path}[${i}]`) 一致。
 * 支持数组和 Record 两种格式。
 */
function collectInteractionZoneGizmoEntries(): GizmoEntry[] {
  const zones = (meta as any).interactionZones;
  if (!zones) return [];

  const entries: GizmoEntry[] = [];

  const collectFromZone = (baseZonePath: string, zone: any): void => {
    const gt = zone?.geometry?.transform;
    if (gt && typeof gt === 'object') {
      entries.push(makeGizmoEntry(`${baseZonePath}.geometry.transform`, gt));
    }
    const mt = zone?.model?.transform;
    if (mt && typeof mt === 'object') {
      entries.push(makeGizmoEntry(`${baseZonePath}.model.transform`, mt));
    }
  };

  if (Array.isArray(zones)) {
    zones.forEach((zone, i) => collectFromZone(`interactionZones[${i}]`, zone));
  } else if (typeof zones === 'object' && zones !== null) {
    // Record 格式：key 是字符串，路径用点号（与 SchemaRenderer joinPath 一致），
    // 不能用方括号 interactionZones[key]——parsePath 只认 [\d+]，
    // 且 isGizmoPathActive 做字符串精确匹配，点号 vs 方括号会对不上。
    for (const [key, zone] of Object.entries(zones)) {
      collectFromZone(`interactionZones.${key}`, zone as any);
    }
  }

  return entries;
}

// 注：v1.6.0 引入的 materializeDefaults（选中 widget 时把 schema 缺失字段写回 meta）
// 在 v1.9.0 被移除——它会污染导入的原始配置（用户的 .json 被静默改动）。
// 替代方案：
// - 属性面板（SchemaRenderer v1.1.0+）按"占位行 vs 编辑控件"区分缺失/已填字段，
//   只有用户主动点"+ 添加"才会真正写入；
// - SDK 渲染需要的兜底由 PreviewPanel.applyRenderDefaults 在 config 副本上做，
//   不影响 meta。

const onAddWidget = (id: string) => {
  const widget = rules.value.widgets.find((w) => w.id === id);
  if (!widget) return;

  // 联合类型 widget：写入第一个 variant 的 defaultSkeleton
  if (widget.variants && widget.variants.length > 0) {
    const firstVariant = widget.variants[0];
    applyVariantSkeleton(id, firstVariant);
    selectedWidgetId.value = id;
    return;
  }

  // 添加策略：按 schema.rootPath 写入一个空骨架，让 SceneTreePanel 的"数据存在"判定通过。
  // - rootPath 含 '.'（如 'initial.camera'）：递归创建中间对象，最终 key 写空字符串占位
  // - rootPath = id：在顶层写一个空对象 {}（数组类的 widget 由属性面板的 emptyDefault 接管真正的初始化）
  // - rootPath = ''（如 camera 这种跨多顶层路径的 widget）：用 visibleInTree 推断需要的最小路径
  const rp = (widget.rootPath || '').trim();

  if (id === 'player') {
    const v = meta as any;
    v.initial = v.initial ?? {};
    v.initial.player = v.initial.player && typeof v.initial.player === 'object' && !Array.isArray(v.initial.player)
      ? v.initial.player
      : {};
    v.initial.player.transform = v.initial.player.transform ?? {
      position: [0, 0, 0],
      rotation: [0, 0, 0],
      scale: [1, 1, 1],
    };
    selectedWidgetId.value = id;
    return;
  }

  if (rp.includes('.')) {
    // 嵌套路径：例如 'initial.camera' → 写 meta.initial.camera = ''
    const parts = rp.split('.');
    let cur: any = meta;
    for (let i = 0; i < parts.length - 1; i++) {
      const p = parts[i];
      if (cur[p] == null || typeof cur[p] !== 'object') cur[p] = {};
      cur = cur[p];
    }
    const last = parts[parts.length - 1];
    if (cur[last] === undefined) cur[last] = '';
  } else if (rp) {
    // 顶层路径：写空对象（数组类 widget 的"空状态"由属性面板内的 emptyDefault 按钮处理）
    if ((meta as any)[rp] === undefined) (meta as any)[rp] = {};
  } else {
    // rootPath = ''：camera 这种跨多顶层路径的 widget，按已知的 visibleInTree 语义决定
    if (id === 'camera') {
      const v = meta as any;
      v.initial = v.initial ?? {};
      // 顶层 camera[] 不存在或空 → 写入一份完整默认相机
      if (!Array.isArray(v.camera) || v.camera.length === 0) {
        const def = buildDefaultCamera();
        v.camera = [def];
        // initial.camera 必须是非空字符串才视为合规引用；其他形态（undefined / '' / 旧版对象 /
        // null / 数组）都视为"待迁移"，覆盖为新创建相机的 id。
        // 这正是从旧版结构（initial.camera = CameraConfig 对象）迁移到新版（id 引用）的转换点。
        const cur = v.initial.camera;
        if (typeof cur !== 'string' || cur === '') {
          v.initial.camera = def.id;
        }
      } else {
        // camera[] 已存在
        const cur = v.initial.camera;
        if (typeof cur !== 'string' || cur === '') {
          // 同上：非合规引用 → 覆盖为第一项 id
          v.initial.camera = v.camera[0]?.id ?? '';
        }
      }
    }
  }

  selectedWidgetId.value = id;
};

/**
 * 将 variant 的 defaultSkeleton 写入 meta。
 * skeleton 的 key 是顶层 key（如 { interactionZones: [] }），直接合并到 meta。
 *
 * 切换 Record ↔ Array 时：
 * - 无数据 → 写入骨架（空数组/空对象）
 * - 有数据，类型匹配 → 保留已有数据
 * - 有数据，类型不匹配 → 保留已有数据不覆盖（保存时 checkTypeConflicts 会警告）
 */
function applyVariantSkeleton(_widgetId: string, variant: WidgetVariant) {
  if (!variant.defaultSkeleton) return;
  const v = meta as any;
  for (const [topKey, targetSkeleton] of Object.entries(variant.defaultSkeleton)) {
    const existing = v[topKey];

    // 无数据 → 写入骨架
    if (existing == null) {
      v[topKey] = targetSkeleton;
      continue;
    }

    // 有数据且类型匹配 → 保留已有数据
    const existingIsArray = Array.isArray(existing);
    const targetIsArray = Array.isArray(targetSkeleton);
    if (existingIsArray === targetIsArray) continue;

    // 类型不匹配 → 保留已有数据，不覆盖（编辑器渲染会用 skeleton fallback 显示空结构）
  }
}




/**
 * 用户在属性面板切换联合类型 variant 时触发。
 * 用新 variant 的 defaultSkeleton 覆盖旧数据。
 */
const onVariantSwitch = (widgetId: string, variant: WidgetVariant) => {
  applyVariantSkeleton(widgetId, variant);
  // variant 切换可能写入含 transform 的骨架（如 union widget 从无数据切到有 transform 的 variant），
  // 需重新收集 gizmo 条目。applyVariantSkeleton 直接 mutate meta 不走 onPropertyChange，
  // 且 selectedWidgetId 不变所以 watch 不触发，必须手动重收集。
  if (selectedWidgetId.value === widgetId) {
    const entries = collectWidgetGizmoEntries(widgetId);
    if (entries.length > 0) {
      activateGizmoMulti(entries);
    } else if (activeGizmoEntries.value.length > 0) {
      deactivateGizmo();
    }
  }
};

const onRemoveWidget = (id: string) => {
  const widget = rules.value.widgets.find((w) => w.id === id);
  if (!widget) return;

  const rp = (widget.rootPath || '').trim();

  if (rp.includes('.')) {
    const parts = rp.split('.');
    let cur: any = meta;
    for (let i = 0; i < parts.length - 1; i++) {
      cur = cur?.[parts[i]];
      if (cur == null) return;
    }
    delete cur[parts[parts.length - 1]];
  } else if (rp) {
    delete (meta as any)[rp];
  } else if (id === 'camera') {
    // 跨多顶层路径：camera widget 的可见性来自 `initial.camera` 或顶层 `camera[]`，
    // 所以删除时两处都要清掉，树节点才会真正消失。
    const v = meta as any;
    if (v.initial && 'camera' in v.initial) delete v.initial.camera;
    if (Array.isArray(v.camera) || 'camera' in v) delete v.camera;
  } else {

    const removableTopLevelPaths = Array.from(new Set((widget.fields ?? [])
      .map((field) => (field.path || '').trim())
      .filter((path) => path && !path.includes('.'))));

    if (removableTopLevelPaths.length === 1) {
      removeAtPath(meta, removableTopLevelPaths[0]);
    }
  }

  if (selectedWidgetId.value === id) selectedWidgetId.value = null;
};


/**
 * 当 PropertyPanel 中数据缺失场景被点击"添加默认数据"按钮时触发。
 *
 * 当前为 demo：仅在控制台提示。后续真正接入数据双向绑定时，
 * 应该按 schema.rootPath 在 value 上写入空对象 {}，
 * 让虚拟节点（如 player → initial.player）的属性面板可编辑。
 */
const onAddDefault = () => {
  // eslint-disable-next-line no-console
  console.log('[MetaEditor] add default for:', selectedWidgetId.value, currentSchema.value?.rootPath);
};

// ==================== 双向绑定：属性面板写回 ====================

/**
 * 叶子字段写回：将 absPath 指向的位置就地 mutate 为 value。
 *
 * - value === undefined → 视为删除该 key（用于 group 启用 checkbox 取消勾选等场景）
 * - 其余 → setByPath 写入
 */
const onPropertyChange = (absPath: string, value: unknown): void => {
  if (!absPath) return;
  if (value === undefined) {
    removeAtPath(meta, absPath);
  } else {
    setByPath(meta, absPath, value);
  }

  // gizmo 激活时，数值面板改值需同步对应 gizmo 的 proxy 位置。
  // 遍历所有激活的 gizmo 条目，找到路径匹配的并同步。
  for (const entry of activeGizmoEntries.value) {
    if (absPath.startsWith(entry.path + '.')) {
      const transform = getByPath(meta, entry.path);
      if (transform && typeof transform === 'object') {
        const newTransform: GizmoTransform = {
          position: [transform.position?.[0] ?? 0, transform.position?.[1] ?? 0, transform.position?.[2] ?? 0],
          rotation: [transform.rotation?.[0] ?? 0, transform.rotation?.[1] ?? 0, transform.rotation?.[2] ?? 0],
          scale: [transform.scale?.[0] ?? 1, transform.scale?.[1] ?? 1, transform.scale?.[2] ?? 1],
        };
        syncGizmoTransform(entry.path, newTransform);
        // 同步更新 activeGizmoEntries 中对应条目的 transform，
        // 确保 gizmo 下次拖拽时 dragStart.metaTransform 使用正确的基准值，
        // 而非激活时的旧值（否则多次拖拽后 delta 会加到过时的 base 上）。
        activeGizmoEntries.value = activeGizmoEntries.value.map((e) =>
          e.path === entry.path ? { ...e, transform: newTransform } : e,
        );
      }
      break;
    }
  }

  // geometry.type 变更 → 自动调整 size 为该 type 的默认参数。
  // 不同 type 的 size 项数不同（box=3, sphere=1, cone=2...），切换时需重置。
  if (absPath.endsWith('.geometry.type') && typeof value === 'string') {
    const DEFAULT_SIZE: Record<string, number[]> = {
      box: [1, 1, 1],
      sphere: [0.5],
      cylinder: [0.5, 0.5, 1],
      cone: [0.5, 1],
      plane: [1, 1],
      circle: [0.5],
      torus: [0.5, 0.15],
    };
    const defaultSize = DEFAULT_SIZE[value];
    if (defaultSize) {
      const sizePath = absPath.replace(/\.type$/, '.size');
      setByPath(meta, sizePath, defaultSize);
    }
  }

  // geometry.size 或 geometry.type 变更 → 通知 PreviewPanel 就地重建几何体网格。
  // gizmo 激活时 suppressRebuild=true 阻止了 SDK 重建，
  // PreviewPanel 需要直接在场景中替换 Mesh 的 geometry。
  if (absPath.includes('.geometry.size') || absPath.includes('.geometry.type')) {
    notifyGeometryChange(absPath);
  }

  // 属性变更可能引入新的 transform 对象（如用户手动添加 geometry 对象），
  // 需重新收集选中 widget 的 gizmo 条目。
  // 仅当变更路径不是已有 gizmo 条目的子路径时才重收集（避免拖拽时频繁重置）。
  // 例外：value === undefined（删除操作）时必须重收集，
  // 因为删除的可能正是 gizmo 条目对应的 transform 对象本身（absPath === entry.path），
  // 此时 isExistingGizmoSubPath 为 true 但数据已不存在，gizmo 应被移除。
  const isExistingGizmoSubPath = activeGizmoEntries.value.some((entry) => {
    if (absPath === entry.path || absPath.startsWith(entry.path + '.')) return true;
    // 同一 geometry/model 对象内的兄弟字段（如 .geometry.type vs .geometry.transform）
    // 视为已存在路径，避免切换 type 时重新激活全部 gizmo
    const entryParent = entry.path.replace(/\.transform$/, '');
    return entryParent !== entry.path && absPath.startsWith(entryParent + '.');
  });
  if ((!isExistingGizmoSubPath || value === undefined) && selectedWidgetId.value) {
    const entries = collectWidgetGizmoEntries(selectedWidgetId.value);
    if (entries.length > 0) {
      // interactionZones 对象格式新增 zone key 时，需等 SDK 重建出对应运行时对象，
      // 否则 PreviewPanel 创建 gizmo 时 sceneTarget=null，只回写数值不更新视觉。
      // 与 onArrayPush 的延迟激活逻辑对齐。
      const isNewInteractionZoneKey =
        selectedWidgetId.value === 'interactionZones' &&
        !isExistingGizmoSubPath &&
        value !== undefined &&
        value != null &&
        typeof value === 'object' &&
        !Array.isArray(value) &&
        Boolean((value as any)?.geometry?.transform || (value as any)?.model?.transform);

      if (isNewInteractionZoneKey) {
        const beforeSdk = sdkRef.value;
        const beforeCounter = sceneReadyCounter.value;
        deactivateGizmo();
        void (async () => {
          await nextTick();
          await waitForSdkRefresh(beforeSdk, beforeCounter);
          if (selectedWidgetId.value) {
            const newEntries = collectWidgetGizmoEntries(selectedWidgetId.value);
            if (newEntries.length > 0) {
              activateGizmoMulti(newEntries);
            }
          }
        })();
      } else {
        activateGizmoMulti(entries);
      }
    } else if (activeGizmoEntries.value.length > 0) {
      deactivateGizmo();
    }
  }
};

/**
 * Gizmo 拖拽回写：PreviewPanel 中 TransformControls 拖动时，
 * 通过 useGizmoBridge 通知到此处，路由到 onPropertyChange 写回 meta。
 *
 * absPath 是 transform 字段的绝对路径（如 "gaussianSplatting.transform"），
 * channel 是 position/rotation/scale 三轴之一。
 */
const { changeHandler, activeGizmoEntries, sdkRef, sceneReadyCounter } = useGizmoBridge();
changeHandler.value = (absPath: string, channel: 'position' | 'rotation' | 'scale' | 'size', value: number[]) => {
  onPropertyChange(`${absPath}.${channel}`, value);
};

const waitForSdkRefresh = async (beforeSdk: any, beforeCounter: number, timeoutMs = 5000): Promise<void> => {
  const start = Date.now();
  let sdkChangedTime: number | null = null;
  while (Date.now() - start < timeoutMs) {
    await new Promise<void>((resolve) => window.setTimeout(resolve, 50));
    if (sdkRef.value && sdkRef.value !== beforeSdk) {
      if (sdkChangedTime === null) sdkChangedTime = Date.now();
      // SDK 重建完成且场景就绪 → 可以安全激活 gizmo
      if (sceneReadyCounter.value !== beforeCounter) return;
      // SDK 已重建但场景 2s 内未触发 onSceneReady → 兜底返回（可能场景无 zone 对象）
      if (Date.now() - sdkChangedTime > 2000) return;
    }
  }
};

const activateNewArrayItemGizmoAfterRender = async (arrAbsPath: string, itemPath: string, item: unknown, beforeSdk: any, beforeCounter: number): Promise<void> => {
  const found: { path: string; transform: any }[] = [];
  findTransformsInData(item, itemPath, found);
  if (found.length === 0) return;

  if (arrAbsPath === 'interactionZones') {
    deactivateGizmo();
    await nextTick();
    await waitForSdkRefresh(beforeSdk, beforeCounter);
  }

  const newEntries = found.map((f) => makeGizmoEntry(f.path, f.transform));
  activateGizmoMulti([...activeGizmoEntries.value, ...newEntries]);
};

/** 数组追加 */
const onArrayPush = async (arrAbsPath: string, item: unknown): Promise<void> => {
  if (!arrAbsPath) return;
  const beforeSdk = sdkRef.value;
  const beforeCounter = sceneReadyCounter.value;
  let arr = getByPath(meta, arrAbsPath);
  if (!Array.isArray(arr)) {
    // 如果已有数据是 Record（非空对象），弹出确认提示，告知会覆盖
    if (arr != null && typeof arr === 'object' && !Array.isArray(arr)) {
      const keys = Object.keys(arr).slice(0, 3);
      const preview = keys.map((k) => `· ${k}`).join('\n');
      const more = Object.keys(arr).length > 3 ? `\n...另有 ${Object.keys(arr).length - 3} 个字段` : '';
      const proceed = await confirmDialog({
        title: '新增数组项：将覆盖现有 Record 数据',
        message:
          `当前 ${arrAbsPath} 为 Record 类型（${Object.keys(arr).length} 个字段）：\n${preview}${more}\n\n` +
          `新增数组项会将以上数据替换为空数组，内容将不可恢复。`,
        okText: '确认覆盖',
        cancelText: '取消',
        variant: 'warn',
      });
      if (!proceed) return;
    }
    setByPath(meta, arrAbsPath, []);
    arr = getByPath(meta, arrAbsPath);
  }
  (arr as unknown[]).push(item);

  // 新增项含 transform → 自动激活 gizmo。
  // interactionZones 数组项需要先等预览 SDK 重建出 zone_0/zone_1 等运行时对象，
  // 否则 PreviewPanel 会先创建 gizmo，导致 sceneTarget=null，只回写数值不更新视觉。
  const newIndex = (arr as unknown[]).length - 1;
  const itemPath = `${arrAbsPath}[${newIndex}]`;
  void activateNewArrayItemGizmoAfterRender(arrAbsPath, itemPath, item, beforeSdk, beforeCounter);
};

/** 数组移除（按索引） */
const onArrayRemove = (arrAbsPath: string, index: number): void => {
  if (!arrAbsPath) return;
  const arr = getByPath(meta, arrAbsPath);
  if (!Array.isArray(arr)) return;
  if (index < 0 || index >= arr.length) return;
  arr.splice(index, 1);

  // 移除的项可能激活了 gizmo → 清理失效条目并重新索引
  const removedPathPrefix = `${arrAbsPath}[${index}]`;
  // 精确匹配：path === prefix 或 path 以 prefix + '.' 或 prefix + '[' 开头
  // （避免 `list[1]` 误匹配 `list[10]`）
  const isRemovedPath = (path: string) =>
    path === removedPathPrefix ||
    path.startsWith(removedPathPrefix + '.') ||
    path.startsWith(removedPathPrefix + '[');
  const survivingEntries = activeGizmoEntries.value.filter((e) => !isRemovedPath(e.path));

  // 重新索引：被删项之后的条目 path 中 [i] 需要减 1
  const reindexed = survivingEntries.map((e) => {
    if (!e.path.startsWith(arrAbsPath + '[')) return e;
    const match = e.path.match(/\[(\d+)\]/);
    if (!match) return e;
    const idx = parseInt(match[1], 10);
    if (idx <= index) return e; // 删项之前的不受影响
    return { ...e, path: e.path.replace(`[${idx}]`, `[${idx - 1}]`) };
  });

  if (reindexed.length !== activeGizmoEntries.value.length || 
      reindexed.some((e, i) => e.path !== activeGizmoEntries.value[i].path)) {
    activateGizmoMulti(reindexed);
  }
};

// ==================== 文件菜单：新建 / 导入 / 导出 ====================

/**
 * 用 setMeta 替代 Object.assign，确保：
 * - 旧 keys 全部清空（避免上一份数据残留）
 * - 写入后立刻跑 normalizeMeta（修非法形态）
 * - 重置选中状态（避免选中已不存在的 widget）
 */
function setMeta(next: Record<string, any>): void {
  for (const k of Object.keys(meta)) delete meta[k];
  Object.assign(meta, next);
  normalizeMeta(meta);
  selectedWidgetId.value = null;
  // 重置 dirty 基准：刚加载的数据视为"干净状态"
  pristineSnapshot.value = JSON.stringify(meta);
}

/**
 * 新建项目：写入与"默认控件 6 个"对齐的最小骨架。
 *
 * **覆盖范围**：与 widget-schemas.ts 中 `required: true` 的 6 个 widget 一一对应：
 *
 * - 顶层标量：`name / rendererScale / debugger / meterScale`
 * - 顶层对象：`gaussianSplatting (SplatConfig 必需子字段)`
 * - 嵌套虚拟节点：`initial.player (position / rotation 必填)`
 *
 * **不写**的字段：
 * - `collision` / `interactive`：ProjectConfig 类型上必需但归为可添加，避免新建
 *   就塞空 URL 控件；用户首次"添加 collision"或"添加 interactive"时再写骨架（onAddWidget）
 * - 其它可选字段（`camera` / `terrain` / `lighting` / 等）：按需添加
 *
 * 默认值原则：
 * - 数值取"中性"默认（缩放=1、阶=0）
 * - URL/路径留空字符串
 * - transform 用 SDK 文档约定默认（rotation 弧度、scale=[1,1,1]）
 */
function buildBlankMeta(): Record<string, any> {
  return buildProjectConfigSkeleton() as Record<string, any>;
}


const importInputRef = ref<HTMLInputElement | null>(null);
const assetsDirInputRef = ref<HTMLInputElement | null>(null);

const onTopBarAction = (
  action: 'new' | 'import' | 'export' | 'load-example' | 'load-assets-dir',
) => {
  if (action === 'new') void doNew();
  else if (action === 'import') void doImport();
  else if (action === 'export') void doExport();
  else if (action === 'load-example') void doLoadExample();
  else if (action === 'load-assets-dir') doLoadAssetsDir();
};

/** 新建：未保存防呆 + 写入空骨架 */
async function doNew(): Promise<void> {
  if (!(await confirmDiscardIfDirty('新建项目', '新建项目将丢弃当前未保存的修改，是否继续？')))
    return;
  // 新建会清空数据，与之关联的本地文件登记也应一并清空（meta 里没有任何字段引用它们）
  FileBundle.clear();
  FileBundle.setAssetsBaseUrl(null);
  setMeta(buildBlankMeta());
}

/** 加载示例：把内置 mock（ChineseGarden）灌进去，方便快速看到所有控件 */
async function doLoadExample(): Promise<void> {
  if (!(await confirmDiscardIfDirty('加载示例', '加载示例将丢弃当前未保存的修改，是否继续？')))
    return;
  // 示例数据全是远程 URL，不会用到本地文件登记，先清掉
  FileBundle.clear();
  FileBundle.setAssetsBaseUrl(null);
  // 深拷贝避免污染 mockMetaJson 的 import 引用
  setMeta(JSON.parse(JSON.stringify(mockMetaJson)));
}

/**
 * Raw 模式"应用"按钮回调：把用户编辑后的 JSON 对象灌进 meta。
 *
 * RawModePanel 已经做过 JSON.parse 和 isObject 校验，这里仅负责整体替换。
 * 复用 setMeta 让 normalizeMeta 自动跑一次（修非法形态），并清空选中态。
 *
 * FileBundle 处理：raw 应用可能改了字段值（指向不同文件 / 改成远程 URL），
 * 此时 FileBundle 中的旧条目可能成为孤儿；做一次 GC 释放内存（不再被任何字段引用的清掉）。
 */
function onRawApply(parsed: Record<string, any>): void {
  setMeta(parsed);
  // GC：以新 meta 为基准，清掉 FileBundle 中不再被引用的本地文件
  const stillReferenced = new Set(collectLocalPathsInMeta(meta));
  for (const [path] of FileBundle.entries()) {
    if (!stillReferenced.has(path)) FileBundle.unregister(path);
  }
  // 用户在 raw 模式应用后通常想看场景层级树效果，自动切回场景编辑 tab
  activeTab.value = 'scene';
}

/** 导入：触发隐藏 input click，文件选完后由 onImportFileChosen 处理 */
/**
 * 导入入口：先弹"来源选择"对话框（本地文件 / 远程 URL），再分发到对应流程。
 *
 * 两种来源的差异点：
 * - **本地**：触发隐藏 `<input type="file">` click，文件选完后由 onImportFileChosen 处理；
 *   .json 单文件流程会再问一次"是否授权目录"以加载相对路径素材。
 * - **远程**：用 fetch 拉 URL，解析为 JSON；如果是相对路径素材，自动以 URL 所在目录
 *   作为 baseURL 调 fetchByPath 拉到 FileBundle（与本地导入对齐）。
 *
 * 用户取消选择来源 / 关闭对话框 → 退出，不做任何改动。
 */
async function doImport(): Promise<void> {
  if (!(await confirmDiscardIfDirty('导入文件', '导入文件将覆盖当前未保存的修改，是否继续？')))
    return;

  const choice = await importSourceDialog();
  if (!choice) return;

  if (choice === 'local') {
    // 重置 value 让连续选同一个文件也能触发 change
    if (importInputRef.value) importInputRef.value.value = '';
    importInputRef.value?.click();
    return;
  }

  // 远程 URL 导入
  await importFromRemoteUrl(choice.url);
}

/**
 * 从远程 URL 导入 .json 配置 + 自动拉取相对路径素材。
 *
 * 流程：
 * 1. fetch URL 拿到 JSON 文本（CORS 失败 / 4xx / Content-Type=html → 报错退出）
 * 2. 解析为对象，setMeta 替换当前 meta
 * 3. 计算 baseURL = URL 去掉文件名后的部分（如 `https://cdn.example.com/proj/splat.json` → `https://cdn.example.com/proj/`）
 * 4. 收集 meta 中相对路径素材，调 fetchByPath(paths, baseUrl) 自动并发下载到 FileBundle
 * 5. 报告加载结果（成功/失败明细）
 *
 * **不做的事**：不弹"目录授权"——远程导入语义就是"从 URL 拉一切"，没必要让用户再选目录。
 */
async function importFromRemoteUrl(url: string): Promise<void> {
  const busy = beginBusy({
    title: '正在加载远程配置',
    detail: url,
    percent: null,
  });
  try {
    let resp: Response;
    try {
      resp = await fetch(url);
    } catch (err) {
      // 跨域 / 网络错误 → fetch 直接 throw（typeof TypeError），错误信息一般是 "Failed to fetch"
      // eslint-disable-next-line no-console
      console.error('[MetaEditor] 远程导入 fetch 失败：', err);
      pushToast({
        type: 'error',
        title: '加载失败',
        message:
          `无法访问该 URL：${(err as Error).message || 'Failed to fetch'}\n\n` +
          `常见原因：\n` +
          `· 远程站点未允许跨域 (CORS)，浏览器阻断了请求\n` +
          `· 网络不通 / DNS 解析失败\n` +
          `· URL 协议不被支持（仅 http/https）\n\n` +
          `若是 CORS 问题，建议把文件下载到本地后用"本地文件"导入。`,
        duration: 9000,
      });
      return;
    }

    if (!resp.ok) {
      pushToast({
        type: 'error',
        title: '加载失败',
        message: `服务器返回 HTTP ${resp.status} ${resp.statusText || ''}`.trim(),
      });
      return;
    }

    // SPA fallback 防御：若返回 HTML 视为"配置文件不存在"
    const ct = resp.headers.get('content-type') || '';
    if (/^text\/html\b/i.test(ct)) {
      pushToast({
        type: 'error',
        title: '加载失败',
        message: '响应不是 JSON 内容（被 SPA 路由兜底为 HTML），URL 指向的配置文件可能不存在',
      });
      return;
    }

    const text = await resp.text();
    let parsed: any;
    try {
      parsed = JSON.parse(text);
    } catch (err) {
      pushToast({
        type: 'error',
        title: '解析失败',
        message: `URL 指向的内容不是合法 JSON：${(err as Error).message}`,
      });
      return;
    }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      pushToast({ type: 'error', message: '导入失败：JSON 根必须是对象' });
      return;
    }

    // 推导 baseURL：URL 去掉文件名后保留目录（含末尾 /）
    // 示例 'https://cdn.example.com/proj/splat.json' → 'https://cdn.example.com/proj/'
    const baseUrl = new URL('.', url).toString();

    // 接管 meta（清空 FileBundle 让远程素材独占）
    // 顺序：先 setAssetsBaseUrl 再 setMeta——这样 PreviewPanel 重建（由 setMeta 触发）
    // 时 baseUrl 已就位，rad/radc 等流式 LOD 格式能正确解析为 absolute URL。
    FileBundle.clear();
    FileBundle.setAssetsBaseUrl(baseUrl);
    setMeta(parsed);

    const localPaths = collectLocalPathsInMeta(meta);
    if (localPaths.length === 0) {
      pushToast({
        type: 'success',
        title: '导入成功',
        message: '已加载远程配置（无相对路径素材）',
        duration: 3500,
      });
      return;
    }

    busy.update({
      title: '加载远程素材',
      detail: `0 / ${localPaths.length}`,
      percent: 0,
    });
    const report = await fetchByPath(localPaths, baseUrl, (p) => {
      busy.update({
        detail: `${p.done} / ${p.total} · ${p.path.split('/').pop() || p.path}`,
        percent: (p.done / p.total) * 100,
      });
    });
    reportLoad(report, '加载远程素材');
  } catch (err) {
    pushToast({
      type: 'error',
      title: '导入失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

const onImportFileChosen = async (e: Event): Promise<void> => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;

  const isZip =
    /\.zip$/i.test(file.name) ||
    file.type === 'application/zip' ||
    file.type === 'application/x-zip-compressed';

  try {
    if (isZip) {
      await importFromZip(file);
    } else {
      await importFromJson(file);
    }
  } catch (err) {
    alert(`导入失败：${(err as Error).message}`);
  }
};

/** .json 单文件导入：原行为 + 自动尝试加载素材
 *
 * 加载素材的策略（按优先级）：
 * 1. **File System Access API**（Chromium 系桌面）：
 *    - 弹 confirm 询问用户是否授权一个目录（建议指向 .json 所在目录），
 *    - 用户授权后，按 meta 中引用的相对路径**精确读取**所需文件（不需要把整目录全加载）。
 *    - 用户取消授权 → 跳过素材加载，仅完成 meta 导入（用户后续可手工上传）。
 * 2. **不支持 FS Access API**（Firefox / Safari 等）：
 *    - 弹 confirm 询问用户是否选择一个目录，确认后用 `<input webkitdirectory>` 让其挑目录，
 *    - 整目录加载，按 meta 引用的路径过滤报告缺失项。
 *    - 用户取消 → 仅完成 meta 导入。
 *
 * 不再做 `fetchByPath` 兜底：相对路径在浏览器里没有"原始 .json 所在目录"的概念，
 * 用 dev server 根猜测命中率几乎为零，反而会刷出一堆 404 噪音。
 */
async function importFromJson(file: File): Promise<void> {
  const busy = beginBusy({
    title: '正在导入',
    detail: `读取 ${file.name}...`,
    percent: null,
  });
  try {
    const text = await file.text();
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      pushToast({ type: 'error', message: '导入失败：JSON 根必须是对象' });
      return;
    }
    // 纯 JSON 导入 → 清空 FileBundle（之前的本地文件登记跟新数据无关）
    // 本地导入没有"远程根目录"概念，重置 baseUrl=null（PreviewPanel 回落到 document.baseURI）
    FileBundle.clear();
    FileBundle.setAssetsBaseUrl(null);
    setMeta(parsed);

    const localPaths = collectLocalPathsInMeta(meta);
    if (localPaths.length === 0) {
      pushToast({
        type: 'success',
        message: `导入成功：${file.name}`,
        duration: 2500,
      });
      return;
    }

    // 暂时收起 busy，避免遮罩盖住浏览器自带的目录授权弹窗
    busy.update({ title: '等待选择素材目录', detail: '请在弹窗中授权 / 选择目录', percent: null });

    await loadAssetsForImportedMeta(file.name, localPaths, busy);
  } catch (err) {
    pushToast({
      type: 'error',
      title: '导入失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

/**
 * 导入 .json 后：让用户选择一个目录授权，然后按 meta 引用的相对路径加载素材。
 *
 * 参数 busy 是已经创建好的进度遮罩实例，本函数负责更新它的文案 / 进度。
 *
 * 行为分支：
 * - 浏览器支持 FS Access API → 先 confirm，确认后调 `pickDirectoryHandle` + `loadFromDirectoryHandle`
 * - 否则 → confirm 后用隐藏的 `<input webkitdirectory>` 让用户挑目录（loadFromFiles）
 * - 用户在任意环节取消 → 仅完成 meta 导入，提示"可后续手工补充"
 */
async function loadAssetsForImportedMeta(
  importedFileName: string,
  localPaths: string[],
  busy: ReturnType<typeof beginBusy>,
): Promise<void> {
  const fileCount = localPaths.length;

  if (isFileSystemAccessSupported()) {
    const ok = await confirmDialog({
      title: '加载本地素材',
      message:
        `检测到 ${importedFileName} 引用了 ${fileCount} 个本地素材。\n` +
        `由于浏览器无法直接读取你电脑上的文件，需要授权一个目录（建议选择 ${importedFileName} 所在目录）。\n\n` +
        `仅会读取配置中明确引用的文件，不会浏览其它内容。`,
      okText: '选择目录授权',
      cancelText: '稍后手动上传',
      variant: 'info',
    });
    if (!ok) {
      pushToast({
        type: 'info',
        title: '已跳过素材加载',
        message: '可在右侧属性面板手工上传所需素材',
        duration: 4000,
      });
      return;
    }

    let dirHandle: Awaited<ReturnType<typeof pickDirectoryHandle>> = null;
    try {
      dirHandle = await pickDirectoryHandle('read');
    } catch (err) {
      // 不支持 / SecurityError 等：降级到 webkitdirectory
      // eslint-disable-next-line no-console
      console.warn('[MetaEditor] pickDirectoryHandle 失败，降级 webkitdirectory：', err);
      await loadAssetsViaWebkitDirectory(localPaths, busy, true);
      return;
    }

    if (!dirHandle) {
      // 用户主动取消授权
      pushToast({
        type: 'info',
        title: '已跳过素材加载',
        message: '可在右侧属性面板手工上传所需素材',
        duration: 4000,
      });
      return;
    }

    busy.update({
      title: '加载本地素材',
      detail: `0 / ${fileCount}`,
      percent: 0,
    });
    const report = await loadFromDirectoryHandle(dirHandle, localPaths, (p) => {
      busy.update({
        detail: `${p.done} / ${p.total} · ${p.path.split('/').pop() || p.path}`,
        percent: (p.done / p.total) * 100,
      });
    });
    reportLoad(report, '加载素材');
    return;
  }

  // 浏览器不支持 FS Access API：弹提示并走 webkitdirectory 兜底
  const ok = await confirmDialog({
    title: '加载本地素材',
    message:
      `检测到 ${importedFileName} 引用了 ${fileCount} 个本地素材。\n` +
      `当前浏览器不支持目录授权 API（仅 Chrome / Edge 支持），需要你手动选择一个包含这些素材的目录。\n\n` +
      `选择目录后，浏览器会读取目录下所有文件（仅读到内存，不会上传到任何服务器）。`,
    okText: '选择目录',
    cancelText: '稍后手动上传',
    variant: 'info',
  });
  if (!ok) {
    pushToast({
      type: 'info',
      title: '已跳过素材加载',
      message: '可在右侧属性面板手工上传所需素材',
      duration: 4000,
    });
    return;
  }
  await loadAssetsViaWebkitDirectory(localPaths, busy, false);
}

/**
 * webkitdirectory 兜底：等待用户在隐藏 input 上选目录，再批量登记。
 *
 * Promise 在 input change 触发后 resolve；超过 60s 未操作或弹窗被关闭无法可靠探测，
 * 但 input 不消费时也无副作用——下次再触发会覆盖。
 *
 * @param fromAccessApiFallback 是否是从 FS Access API 失败降级而来（影响提示文案）
 */
async function loadAssetsViaWebkitDirectory(
  localPaths: string[],
  busy: ReturnType<typeof beginBusy>,
  fromAccessApiFallback: boolean,
): Promise<void> {
  const inputEl = assetsDirInputRef.value;
  if (!inputEl) {
    pushToast({ type: 'error', message: '内部错误：目录选择 input 未就绪' });
    return;
  }
  inputEl.value = '';

  // 用一个一次性的 change 监听把异步流程串起来
  const filesPromise = new Promise<FileList | null>((resolve) => {
    const handler = () => {
      inputEl.removeEventListener('change', handler);
      resolve(inputEl.files && inputEl.files.length > 0 ? inputEl.files : null);
    };
    inputEl.addEventListener('change', handler);
    inputEl.click();
  });

  busy.update({
    title: '等待选择素材目录',
    detail: fromAccessApiFallback ? '已降级到目录选择' : '请在弹窗中选择目录',
    percent: null,
  });

  const files = await filesPromise;
  if (!files) {
    pushToast({
      type: 'info',
      title: '已跳过素材加载',
      message: '可在右侧属性面板手工上传所需素材',
      duration: 4000,
    });
    return;
  }

  busy.update({
    title: '加载本地素材',
    detail: `处理 ${files.length} 个文件...`,
    percent: null,
  });
  const report = loadFromFiles(files, localPaths);
  reportLoad(report, '加载素材');
}

/** 加载素材目录：用户选一个目录，把里面的文件按相对路径登记到 FileBundle */
function doLoadAssetsDir(): void {
  if (isEmptyMeta.value) {
    pushToast({
      type: 'warn',
      message: '请先新建或导入项目，再加载素材目录',
    });
    return;
  }
  if (assetsDirInputRef.value) assetsDirInputRef.value.value = '';
  assetsDirInputRef.value?.click();
}

const onAssetsDirChosen = (e: Event): void => {
  const input = e.target as HTMLInputElement;
  if (!input.files || input.files.length === 0) return;
  const expected = collectLocalPathsInMeta(meta);
  const report = loadFromFiles(input.files, expected);
  reportLoad(report, '加载素材目录');
};

/**
 * 统一上报加载结果：
 * - 全部成功 → 绿色成功 toast
 * - 部分失败 → 黄色警告 toast，列出前若干条
 * - 全部失败 → 红色错误 toast
 *
 * 失败明细同时打印到 console，方便复制定位。
 */
function reportLoad(report: LoadReport, action: string): void {
  if (report.failed.length === 0 && report.succeeded.length > 0) {
    pushToast({
      type: 'success',
      title: `${action}成功`,
      message: `已加载 ${report.succeeded.length} 个素材文件`,
      duration: 3000,
    });
    return;
  }
  if (report.failed.length > 0) {
    // 控制台详细日志
    // eslint-disable-next-line no-console
    console.warn(
      `[MetaEditor] ${action} 部分失败：`,
      report.failed.map((f) => `${f.path} (${f.reason})`).join('\n'),
    );
    const sample = report.failed.slice(0, 3).map((f) => f.path).join('\n');
    const more = report.failed.length > 3 ? `\n...另有 ${report.failed.length - 3} 个` : '';
    const allFailed = report.succeeded.length === 0;
    pushToast({
      type: allFailed ? 'error' : 'warn',
      title: allFailed ? `${action}失败` : `${action}部分成功`,
      message:
        (allFailed
          ? `${report.failed.length} 个素材无法加载（详见 Console）：\n`
          : `成功 ${report.succeeded.length} 个，${report.failed.length} 个未找到：\n`) +
        sample +
        more,
      duration: 5500,
    });
  }
}

/**
 * .zip 项目包导入：
 * 1) 找到 zip 内的 `meta.json` 作为主配置
 * 2) 其它文件全部回填 FileBundle，路径 = zip 内相对路径
 * 3) FileBundle 中的路径形态应与 meta.json 内字段值一致（约定：相对路径）
 */
async function importFromZip(file: File): Promise<void> {
  const busy = beginBusy({
    title: '正在导入 zip',
    detail: `解析 ${file.name}...`,
    percent: 0,
  });
  try {
    // JSZip 的 loadAsync 也支持 onUpdate 回调，但只覆盖"读取/解压"阶段；
    // 我们后续 forEach 取每个文件 bytes 才是真正的解码工作，所以分两段进度统计。
    const zip = await JSZip.loadAsync(file);
    const metaEntry = zip.file('meta.json');
    if (!metaEntry) {
      pushToast({
        type: 'error',
        title: '导入失败',
        message: 'zip 包内未找到 meta.json',
      });
      return;
    }
    const metaText = await metaEntry.async('string');
    const parsed = JSON.parse(metaText);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      pushToast({
        type: 'error',
        title: '导入失败',
        message: 'meta.json 根必须是对象',
      });
      return;
    }

    // 收集待解压的非 meta.json 条目（先 enumerate 出来，方便算总数 + 推进度）
    const pending: Array<{ relPath: string; entry: import('jszip').JSZipObject }> = [];
    zip.forEach((relPath, zipEntry) => {
      if (zipEntry.dir) return;
      if (relPath === 'meta.json') return;
      pending.push({ relPath, entry: zipEntry });
    });

    // 重置 FileBundle，再串行回填（串行比 Promise.all 慢一点但能精确推进度）
    // zip 导入没有"远程根目录"概念，重置 baseUrl=null
    FileBundle.clear();
    FileBundle.setAssetsBaseUrl(null);
    busy.update({ detail: `0 / ${pending.length}`, percent: 0 });
    for (let i = 0; i < pending.length; i++) {
      const { relPath, entry } = pending[i];
      const bytes = await entry.async('uint8array');
      FileBundle.register(relPath, bytes);
      busy.update({
        detail: `${i + 1} / ${pending.length} · ${relPath.split('/').pop() || relPath}`,
        percent: ((i + 1) / Math.max(pending.length, 1)) * 100,
      });
    }

    setMeta(parsed);
    pushToast({
      type: 'success',
      title: '导入成功',
      message: `已加载 ${pending.length} 个素材文件`,
      duration: 3000,
    });
  } catch (err) {
    pushToast({
      type: 'error',
      title: '导入 zip 失败',
      message: (err as Error).message || String(err),
    });
  } finally {
    busy.end();
  }
}

/**
 * 导出：
 * - 当存在被引用的本地文件 → 打成 zip（meta.json + 各子目录文件）
 * - 否则 → 单文件 .json 下载（保持轻量场景的体验）
 *
 * 文件路径约定：meta 中字段值（如 collision.url='collision/x.glb'）即为 zip 内的相对路径，
 * FileBundle 的 key 与之一一对应，导出时仅打包 meta 中"实际引用到"的本地文件，
 * 不再被引用的孤儿文件会被 GC（不进 zip）。
 *
 * **UI 锁定**：zip 模式下打包是异步的，期间用 BusyOverlay 锁住 UI，避免用户继续编辑导致打包内容前后不一致。
 */
async function doExport(): Promise<void> {
  if (isEmptyMeta.value) {
    pushToast({
      type: 'warn',
      message: '当前没有可导出的数据，请先新建或导入项目',
    });
    return;
  }

  // 必填校验：在生成 snapshot 前跑一次，告诉用户有哪些字段没填。
  // 失败时弹 confirm 让用户选择 "继续导出" / "取消修复"——校验是提示性的，
  // 不强制阻塞（用户可能就是想导出半成品备份）。
  const report = validateRequiredFields(meta, rules.value);
  if (!report.ok) {
    const lines: string[] = [];
    if (report.violations.length > 0) {
      lines.push('· ' + report.violations.join('\n· '));
    }
    if (report.missing.length > 0) {
      const sample = report.missing.slice(0, 8);
      lines.push(
        ...sample.map((m) => `· ${m.widgetId}: ${m.label}（${m.absPath}）`),
      );
      if (report.missing.length > sample.length) {
        lines.push(`...另有 ${report.missing.length - sample.length} 项必填字段未填`);
      }
    }
    const proceed = await confirmDialog({
      title: '导出前检查：存在未配置的必填项',
      message:
        `以下字段是 SDK 渲染场景所必需的，但当前 meta 中缺失：\n\n${lines.join('\n')}\n\n` +
        `继续导出会得到一份"半成品"配置，SDK 加载时会报错。建议先回属性面板补齐再导出。`,
      okText: '仍然导出',
      cancelText: '回去补齐',
      variant: 'warn',
    });
    if (!proceed) return;
  }

  const snapshot = JSON.parse(JSON.stringify(meta));
  const fileName = `${(snapshot.name || 'meta').toString().trim() || 'meta'}`;

  // 收集 meta 实际引用到的本地路径（避免把已删除字段对应的孤儿文件也打进去）
  const referenced = collectLocalPathsInMeta(snapshot);
  const referencedExisting = referenced.filter((p) => FileBundle.has(p));
  const missing = referenced.filter((p) => !FileBundle.has(p));

  if (referencedExisting.length === 0) {
    // 纯远程 / 无本地文件登记：单 .json 下载（同步快操作，不需要进度条）
    downloadBlob(
      JSON.stringify(snapshot, null, 2),
      `${fileName}.json`,
      'application/json;charset=utf-8',
    );
    if (missing.length > 0) {
      pushToast({
        type: 'warn',
        title: '已导出 JSON（不含素材）',
        message: `检测到 ${missing.length} 个本地素材引用未加载，导出仅含 meta.json`,
        duration: 6000,
      });
    } else {
      pushToast({
        type: 'success',
        message: `已导出 ${fileName}.json`,
        duration: 2500,
      });
    }
  } else {
    // 含本地文件：打 zip（耗时操作，锁 UI + 显示进度）
    await exportAsZip(snapshot, referencedExisting, fileName);
    const tip =
      missing.length > 0
        ? `已打包 ${referencedExisting.length} 个素材，仍有 ${missing.length} 个未加载（详见 Console）`
        : `已打包 ${referencedExisting.length} 个素材`;
    if (missing.length > 0) {
      // eslint-disable-next-line no-console
      console.warn('[MetaEditor] 导出 zip 中缺失的素材路径：', missing);
    }
    pushToast({
      type: missing.length > 0 ? 'warn' : 'success',
      title: `已导出 ${fileName}.zip`,
      message: tip,
      duration: 3500,
    });
  }

  // 导出 == 落地保存：重置 dirty 基准
  pristineSnapshot.value = JSON.stringify(meta);
}

/**
 * 用 JSZip 把 meta.json + 所有被引用的本地文件打包下载。
 *
 * 进度阶段：
 * 1) 写入 meta.json + 各文件条目（瞬时，进度从 0 → 5）
 * 2) `zip.generateAsync` 生成 blob（耗时，由 onUpdate 回调推 5 → 95）
 * 3) Blob 生成完毕到触发下载（95 → 100）
 *
 * 期间用 BusyOverlay 锁 UI，try/finally 确保异常时也能释放。
 *
 * **进度平滑**：JSZip 对小文件 / 已压缩资源（splat/glb 等）的 onUpdate 触发非常稀疏，
 * 容易出现"卡在 37% 然后直接 100%"的视觉错觉。这里用一个 setInterval 平滑器：
 * - onUpdate 拿到真实进度 → 作为"目标值"
 * - 平滑器每 50ms 把显示进度向目标值靠拢（每步最多 +1.5）
 * - 这样视觉上始终是连续过渡，不影响真实完成时机（完成后强制拉满）
 */
async function exportAsZip(
  snapshot: Record<string, any>,
  paths: string[],
  fileName: string,
): Promise<void> {
  const busy = beginBusy({
    title: '正在导出 zip',
    detail: '准备文件...',
    percent: 0,
  });

  // 进度平滑器：targetPercent 是 onUpdate 给的真值，displayPercent 是 UI 显示值
  let targetPercent = 5;
  let displayPercent = 0;
  let currentFileLabel = '准备文件...';
  const smoother = window.setInterval(() => {
    if (displayPercent < targetPercent) {
      // 距离越远走得越快，但单次最多 +1.5%，保持视觉平滑
      const gap = targetPercent - displayPercent;
      const step = Math.min(1.5, Math.max(0.3, gap * 0.15));
      displayPercent = Math.min(targetPercent, displayPercent + step);
      busy.update({ detail: currentFileLabel, percent: displayPercent });
    }
  }, 50);

  try {
    const zip = new JSZip();
    zip.file('meta.json', JSON.stringify(snapshot, null, 2));

    for (const path of paths) {
      const entry = FileBundle.get(path);
      if (!entry) continue;
      // zip 内路径用规范化形式（不带前导 ./ 或 /），避免不同打包工具的兼容问题。
      // meta.json 中字段值保持用户原样写法（含 ./），下次解压时 FileBundle.normalizePath 让两边对齐。
      const zipPath = FileBundle.normalizePath(path);
      zip.file(zipPath, entry as Blob | Uint8Array);
    }

    targetPercent = 5;
    currentFileLabel = '压缩中...';

    const blob = await zip.generateAsync(
      {
        type: 'blob',
        compression: 'DEFLATE',
        compressionOptions: { level: 6 },
      },
      (metadata) => {
        // metadata.percent 是 0-100；映射到 5-95 区间，给前置和收尾各留 5%
        targetPercent = 5 + (metadata.percent / 100) * 90;
        currentFileLabel = metadata.currentFile
          ? `压缩中：${metadata.currentFile.split('/').pop() || metadata.currentFile}`
          : '压缩中...';
      },
    );

    // 压缩已完成 → 把目标拉到 95；后面触发下载再拉满 100
    targetPercent = 95;
    currentFileLabel = '触发下载...';

    // 下载
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fileName}.zip`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);

    // 强制拉满（停止平滑器后立即推到 100，避免最后还卡几个百分点）
    targetPercent = 100;
    displayPercent = 100;
    busy.update({ detail: '完成', percent: 100 });
  } finally {
    window.clearInterval(smoother);
    busy.end();
  }
}

/** 触发浏览器下载（纯文本/单文件场景） */
function downloadBlob(content: string, fileName: string, mime: string): void {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * 收集 meta 中"应当作为本地素材打包"的字符串值。
 *
 * **严格基于 rules 的字段声明**：只扫描那些在 widget-schemas 中显式标记了 `bundleDir` 的
 * FieldUrl 字段。其它字符串字段（无论看起来多像路径）一律不参与打包，避免把：
 *
 * - npc 名字（`'默认相机'`、`'去看看'`）
 * - 模型 url（如果用户填了相对路径但该字段未声明 bundleDir）
 * - 按钮文案、提示语
 *
 * 当成"本地素材"误打包。
 *
 * 当前规则中标记 bundleDir 的字段（可在 widget-schemas.ts 中检索 `bundleDir:`）：
 * - `collision.url`
 * - `gaussianSplatting.singleSceneConfigPath`
 * - `gaussianSplatting.regionReplaceConfigPath`
 *
 * 未来需要扩展时，只要在 widget-schemas.ts 增加 `bundleDir` 即可，本函数零改动。
 *
 * @returns 唯一化后的本地路径列表（去重）
 */
function collectLocalPathsInMeta(value: any): string[] {
  // 1) 从 rules 反查所有 bundle 字段的"绝对路径"
  const bundleAbsPaths: string[] = [];
  collectBundleFieldPaths(rules.value.widgets, '', bundleAbsPaths);

  // 2) 按这些绝对路径取值
  const out: string[] = [];
  const seen = new Set<string>();
  for (const absPath of bundleAbsPaths) {
    const v = getByPath(value, absPath);
    if (typeof v === 'string' && FileBundle.isLocalPath(v)) {
      // 用 normalize 后的 path 做唯一化键，避免 './x' 和 'x' 重复
      const key = FileBundle.normalizePath(v);
      if (!seen.has(key)) {
        seen.add(key);
        out.push(v);
      }
    }
  }
  return out;
}

/**
 * 递归遍历 widget schema，收集所有标记了 bundleDir 的 FieldUrl 字段的绝对路径。
 *
 * 绝对路径 = `widget.rootPath` + `field.path` 拼接（中间用 `.`）。
 * 注意 array/group 内部的 FieldUrl 也会被包含——递归 children/itemSchema。
 */
function collectBundleFieldPaths(
  widgets: WidgetSchema[],
  _basePath: string,
  out: string[],
): void {
  for (const w of widgets) {
    if (!w.fields) continue;
    walkFields(w.fields, w.rootPath || '', out);
  }
}

function walkFields(fields: any[], basePath: string, out: string[]): void {
  for (const f of fields) {
    if (!f || typeof f !== 'object') continue;
    const fPath = f.path || '';
    const abs = joinPath(basePath, fPath);

    if (f.type === 'url' && f.bundleDir) {
      out.push(abs);
    } else if (f.type === 'group' && Array.isArray(f.children)) {
      walkFields(f.children, abs, out);
    }
    // array.itemSchema 暂不参与（当前 3 个 bundleDir 字段都不在数组里；
    // 未来若有数组内的 bundle 字段，需要按 'arr[0].field' / 'arr[1].field' 展开实例）
  }
}

function joinPath(a: string, b: string): string {
  if (!a) return b;
  if (!b) return a;
  return `${a}.${b}`;
}

/**
 * "是否丢弃未保存内容"防呆。
 *
 * 触发条件：仅当 isDirty（meta 相对 pristine 快照有变更）时弹自定义 Confirm 对话框。
 * - 空白态 / 加载后未编辑：直接放行不打扰
 * - 真实有改动：弹 ConfirmDialog（异步等待用户决策）
 *
 * 使用 confirmDialog（自定义对话框）而不是 window.confirm 的原因：
 * - 视觉与编辑器暗色主题一致，居中显示，焦点自动落在"确定"按钮
 * - Esc / Enter 键支持
 * - 浏览器原生 confirm 在某些设备上"阻止后续脚本"行为不一致
 */
async function confirmDiscardIfDirty(title: string, message: string): Promise<boolean> {
  if (!isDirty.value) return true;
  return confirmDialog({
    title,
    message,
    okText: '继续',
    cancelText: '取消',
    variant: 'danger',
  });
}

/**
 * 浏览器关闭/刷新页面时的防丢提示。
 *
 * 使用 beforeunload 标准事件：现代浏览器要求同时设置 preventDefault() 和 returnValue
 * 才会显示原生确认弹窗（文案由浏览器决定，不能自定义；我们只决定是否提醒）。
 *
 * 注意：returnValue 在标准上已 deprecated，但所有主流浏览器（Chrome/Firefox/Safari/Edge）
 * 仍要求这个属性才会显示提示——是事实标准。这里 ts-ignore 抑制弃用警告。
 */
const onBeforeUnload = (e: BeforeUnloadEvent) => {
  if (isDirty.value) {
    e.preventDefault();
    // returnValue 已 deprecated 但浏览器仍要求设置才显示弹窗，是事实标准
    // eslint-disable-next-line @typescript-eslint/no-deprecated, deprecation/deprecation
    e.returnValue = '';
  }
};
</script>

