-->
<template>
  <div class="url-field">
    <div class="url-mode-tabs">
      <label class="me-radio">
        <input type="radio" :name="modeName" :checked="currentMode === 'remote'" @change="currentMode = 'remote'" />
        <Globe :size="12" />
        <span>远程 URL</span>
      </label>
      <label
        class="me-radio"
        :class="{ disabled: !bundleDir }"
        :title="!bundleDir ? '本字段暂不支持本地导入' : ''"
      >
        <input
          type="radio"
          :name="modeName"
          :checked="currentMode === 'local'"
          :disabled="!bundleDir"
          @change="currentMode = 'local'"
        />
        <HardDrive :size="12" />
        <span>本地文件</span>
      </label>
    </div>

    <input
      v-if="currentMode === 'remote'"
      class="me-input me-input-mono"
      type="text"
      :placeholder="placeholder"
      :value="value"
      @input="onUrlInput"
    />

    <div v-else class="local-zone" @dragover.prevent @drop.prevent="onDrop">
      <div class="file-info">
        <FileText :size="14" />
        <span class="file-name me-mono">{{ value || '尚未选择文件' }}</span>
        <span v-if="boundFile" class="file-size">{{ formattedSize }}</span>
      </div>
      <div class="file-actions">
        <button class="me-btn me-btn-sm" type="button" @click="onPickFile">
          <Upload :size="12" />
          {{ value ? '替换文件' : '选择文件' }}
        </button>
        <button
          v-if="value"
          class="me-btn me-btn-sm danger"
          type="button"
          title="移除本地文件登记"
          @click="onClearFile"
        >
          <Trash2 :size="12" />
          移除
        </button>
        <span class="drop-hint">
          <MousePointer2 :size="11" />
          也可拖拽到此区域
        </span>
      </div>
      <!-- 隐藏的真实 input -->
      <input
        ref="fileInputRef"
        class="hidden-file-input"
        type="file"
        :accept="accept || ''"
        @change="onFileChosen"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, watch, computed } from 'vue';
import { Globe, HardDrive, FileText, Upload, MousePointer2, Trash2 } from 'lucide-vue-next';
import * as FileBundle from '../schema/file-bundle';

const props = withDefaults(
  defineProps<{
    mode?: 'remote' | 'local';
    value?: string;
    placeholder?: string;
    modeName: string;
    /** 本地文件 zip 子目录（来自 FieldUrl.bundleDir）；未提供时禁用本地模式 */
    bundleDir?: string;
    /** input[type=file] 的 accept 属性（来自 FieldUrl.accept） */
    accept?: string;
  }>(),
  { mode: 'remote', value: '', placeholder: 'https://...' },
);

const emit = defineEmits<{
  (e: 'update:value', v: string): void;
}>();

const currentMode = ref<'remote' | 'local'>(props.mode);
const fileInputRef = ref<HTMLInputElement | null>(null);

watch(() => props.mode, (m) => (currentMode.value = m));

const onUrlInput = (e: Event) => {
  emit('update:value', (e.target as HTMLInputElement).value);
};

/** 当前 value 在 FileBundle 中对应的 File（若已上传） */
const boundFile = computed(() => {
  if (!props.value || !FileBundle.isLocalPath(props.value)) return null;
  return FileBundle.get(props.value);
});

const formattedSize = computed(() => {
  if (!boundFile.value) return '';
  const size = boundFile.value instanceof File
    ? boundFile.value.size
    : boundFile.value.byteLength;
  return FileBundle.formatSize(size);
});

const onPickFile = () => {
  if (!props.bundleDir) return;
  fileInputRef.value?.click();
};

const onFileChosen = (e: Event) => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;
  registerLocalFile(file);
  // 重置 input 让连续选同一个文件也能触发
  input.value = '';
};

const onDrop = (e: DragEvent) => {
  if (!props.bundleDir) return;
  const file = e.dataTransfer?.files?.[0];
  if (!file) return;
  registerLocalFile(file);
};

/**
 * 实际执行登记：
 * 1) 如果当前 value 是本地路径，先从 FileBundle 移除（替换语义）
 * 2) 在 bundleDir 下生成不冲突的新路径
 * 3) 注册文件
 * 4) emit 新路径作为字段值
 *
 * **路径策略（A 案，2026-05 决策）**：
 * 不论当前字段值是空、远程 URL、还是 JSON 里写好的本地路径约定（如 `'./my-region/abc.json'`），
 * 用户上传/替换时，新文件路径**统一**走 `${bundleDir}/${safeFileName}`（如 `single-scene/xxx.json`）。
 *
 * 这意味着用户在 meta.json 里写的旧路径约定会被覆盖。原因：
 * - 编辑器有"打包目录"的统一规范（`single-scene/` `collision/`），与导出 zip 的目录结构对齐
 * - 智能保留旧目录会引入"用户路径 vs 规范目录"的二义性，行为不可预期
 * - 用户如果有特殊路径需求，应直接在 raw 模式编辑字段值
 *
 * 重名冲突由 `uniquePath` 自动加 `(1)` `(2)` 后缀处理，不会互相覆盖。
 */
function registerLocalFile(file: File) {
  if (!props.bundleDir) return;
  // 替换：先清掉旧的登记
  if (props.value && FileBundle.isLocalPath(props.value) && FileBundle.has(props.value)) {
    FileBundle.unregister(props.value);
  }
  const path = FileBundle.uniquePath(props.bundleDir, file.name);
  FileBundle.register(path, file);
  emit('update:value', path);
}

/** 移除按钮：清除登记 + 字段值清空 */
const onClearFile = () => {
  if (props.value && FileBundle.has(props.value)) {
    FileBundle.unregister(props.value);
  }
  emit('update:value', '');
};
</script>

